-- ============================================================================
-- Business logic. Everything the client can do goes through these functions;
-- tables stay read-only for customers. All money and stock maths is server-side.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Encryption helpers for the stock vault
-- ---------------------------------------------------------------------------
create or replace function private.stock_key()
returns text
language sql
stable
security definer
set search_path = ''
as $$ select value from private.secrets where name = 'stock_key'; $$;

create or replace function private.encrypt_payload(p_plain text)
returns bytea
language sql
stable
security definer
set search_path = ''
as $$
  select extensions.pgp_sym_encrypt(p_plain, private.stock_key(), 'cipher-algo=aes256');
$$;

create or replace function private.decrypt_payload(p_enc bytea)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select extensions.pgp_sym_decrypt(p_enc, private.stock_key());
$$;

-- ---------------------------------------------------------------------------
-- Order numbers
-- ---------------------------------------------------------------------------
create or replace function private.new_order_no()
returns text
language plpgsql
volatile
set search_path = ''
as $$
declare v text;
begin
  loop
    v := 'YP' || to_char(now() at time zone 'UTC', 'YYMMDD')
             || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 6));
    exit when not exists (select 1 from public.orders o where o.order_no = v);
  end loop;
  return v;
end;
$$;

-- ---------------------------------------------------------------------------
-- Wallet ledger. Row-locks the profile so concurrent debits cannot oversell.
-- ---------------------------------------------------------------------------
create or replace function private.credit_wallet(
  p_user_id  uuid,
  p_amount   numeric,
  p_kind     public.wallet_kind,
  p_order_id uuid default null,
  p_note     text default null
)
returns numeric
language plpgsql
security definer
set search_path = ''
as $$
declare v_balance numeric(12, 2);
begin
  update public.profiles
     set wallet_balance = wallet_balance + p_amount
   where id = p_user_id
  returning wallet_balance into v_balance;

  if not found then
    raise exception 'profile_not_found';
  end if;

  insert into public.wallet_transactions (user_id, kind, amount_usd, balance_after, order_id, note)
  values (p_user_id, p_kind, p_amount, v_balance, p_order_id, p_note);

  return v_balance;
end;
$$;

-- ---------------------------------------------------------------------------
-- Coupon validation (read-only preview + authoritative use inside create_order)
-- ---------------------------------------------------------------------------
create or replace function private.coupon_discount(
  p_code     text,
  p_user_id  uuid,
  p_subtotal numeric
)
returns numeric
language plpgsql
stable
security definer
set search_path = ''
as $$
declare c public.coupons;
begin
  if p_code is null or btrim(p_code) = '' then
    return 0;
  end if;

  select * into c from public.coupons
   where upper(code) = upper(btrim(p_code))
     and is_active
     and starts_at <= now()
     and (expires_at is null or expires_at > now());

  if not found then
    raise exception 'coupon_invalid';
  end if;

  if c.max_uses is not null and c.used_count >= c.max_uses then
    raise exception 'coupon_exhausted';
  end if;

  if p_subtotal < c.min_order_usd then
    raise exception 'coupon_min_order' using detail = c.min_order_usd::text;
  end if;

  if p_user_id is not null and exists (
    select 1 from public.coupon_redemptions r
    where r.coupon_id = c.id and r.user_id = p_user_id
    group by r.coupon_id having count(*) >= c.per_user_limit
  ) then
    raise exception 'coupon_user_limit';
  end if;

  return case
    when c.kind = 'percent' then round(p_subtotal * c.value / 100, 2)
    else least(c.value, p_subtotal)
  end;
end;
$$;

create or replace function public.validate_coupon(p_code text, p_subtotal numeric)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare v_discount numeric;
begin
  v_discount := private.coupon_discount(p_code, (select auth.uid()), p_subtotal);
  return jsonb_build_object('ok', true, 'discount_usd', v_discount);
exception
  when others then
    return jsonb_build_object('ok', false, 'reason', sqlerrm);
end;
$$;

grant execute on function public.validate_coupon(text, numeric) to authenticated;

-- ---------------------------------------------------------------------------
-- create_order: prices are always recomputed from the catalogue.
-- p_items: [{"variant_id": 1, "qty": 2}, ...]
-- ---------------------------------------------------------------------------
create or replace function public.create_order(
  p_items   jsonb,
  p_coupon  text default null,
  p_fields  jsonb default '{}'::jsonb,
  p_email   text default null,
  p_note    text default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user       uuid := (select auth.uid());
  v_profile    public.profiles;
  v_item       jsonb;
  v_variant    public.product_variants;
  v_product    public.products;
  v_qty        integer;
  v_stock      integer;
  v_subtotal   numeric(12, 2) := 0;
  v_discount   numeric(12, 2) := 0;
  v_total      numeric(12, 2);
  v_order_id   uuid;
  v_order_no   text;
  v_ttl        integer;
  v_required   jsonb;
  v_missing    text;
  v_has_stock  boolean := false;
begin
  if v_user is null then
    raise exception 'auth_required';
  end if;

  select * into v_profile from public.profiles where id = v_user;
  if v_profile.is_blocked then
    raise exception 'account_blocked';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'empty_cart';
  end if;

  if jsonb_array_length(p_items) > 20 then
    raise exception 'too_many_lines';
  end if;

  select order_ttl_minutes into v_ttl from public.settings where id;

  v_order_no := private.new_order_no();

  insert into public.orders (
    order_no, user_id, status, contact_email, customer_note, customer_fields, coupon_code, expires_at
  ) values (
    v_order_no, v_user, 'pending', p_email, p_note, coalesce(p_fields, '{}'::jsonb),
    nullif(btrim(coalesce(p_coupon, '')), ''),
    now() + make_interval(mins => v_ttl)
  ) returning id into v_order_id;

  for v_item in select * from jsonb_array_elements(p_items)
  loop
    v_qty := greatest(coalesce((v_item ->> 'qty')::integer, 1), 1);

    select * into v_variant
      from public.product_variants
     where id = (v_item ->> 'variant_id')::bigint
       and is_active;

    if not found then
      raise exception 'variant_unavailable' using detail = (v_item ->> 'variant_id');
    end if;

    select * into v_product from public.products where id = v_variant.product_id and is_active;
    if not found then
      raise exception 'product_unavailable';
    end if;

    if v_qty < v_variant.min_qty or v_qty > v_variant.max_qty then
      raise exception 'qty_out_of_range' using detail = v_variant.sku;
    end if;

    -- Per-product buyer fields (game id, server, ...)
    if v_product.requires_fields is not null and jsonb_array_length(v_product.requires_fields) > 0 then
      select string_agg(f ->> 'key', ', ')
        into v_missing
        from jsonb_array_elements(v_product.requires_fields) f
       where coalesce(btrim(p_fields ->> (f ->> 'key')), '') = '';

      if v_missing is not null then
        raise exception 'missing_fields' using detail = v_missing;
      end if;
    end if;

    if v_variant.stock_mode = 'stock' then
      select count(*) into v_stock
        from private.stock_items s
       where s.variant_id = v_variant.id and s.status = 'available';

      if v_stock < v_qty then
        raise exception 'out_of_stock' using detail = v_variant.sku;
      end if;
      v_has_stock := true;
    end if;

    v_subtotal := v_subtotal + (v_variant.price_usd * v_qty);

    insert into public.order_items (
      order_id, variant_id, product_name, variant_label,
      unit_price_usd, qty, line_total_usd, unit_cost_usd
    ) values (
      v_order_id, v_variant.id, v_product.name_km, v_variant.label_km,
      v_variant.price_usd, v_qty, v_variant.price_usd * v_qty, v_variant.cost_usd
    );
  end loop;

  v_discount := private.coupon_discount(p_coupon, v_user, v_subtotal);
  v_total := greatest(v_subtotal - v_discount, 0);

  update public.orders
     set subtotal_usd = v_subtotal,
         discount_usd = v_discount,
         total_usd    = v_total
   where id = v_order_id;

  return jsonb_build_object(
    'order_id', v_order_id,
    'order_no', v_order_no,
    'subtotal_usd', v_subtotal,
    'discount_usd', v_discount,
    'total_usd', v_total,
    'expires_in_minutes', v_ttl
  );
end;
$$;

grant execute on function public.create_order(jsonb, text, jsonb, text, text) to authenticated;

-- ---------------------------------------------------------------------------
-- Delivery: atomic stock pickup, then per-kind handling
-- ---------------------------------------------------------------------------
create or replace function private.deliver_order(p_order_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_item      record;
  v_picked    integer;
  v_pending   integer;
  v_waiting   integer;
  v_all_done  boolean;
begin
  update public.orders set status = 'delivering' where id = p_order_id and status = 'paid';

  for v_item in
    select oi.id, oi.variant_id, oi.qty, p.kind, oi.product_name
      from public.order_items oi
      join public.product_variants v on v.id = oi.variant_id
      join public.products p on p.id = v.product_id
     where oi.order_id = p_order_id
       and oi.delivery_status = 'pending'
     order by oi.id
  loop
    if v_item.kind = 'instant_stock' then
      -- The one statement that prevents double-selling.
      update private.stock_items s
         set status = 'sold', order_id = p_order_id, sold_at = now()
       where s.id in (
         select id
           from private.stock_items
          where variant_id = v_item.variant_id
            and status = 'available'
          order by created_at
          limit v_item.qty
          for update skip locked
       );

      get diagnostics v_picked = row_count;

      if v_picked = v_item.qty then
        update public.order_items
           set delivery_status = 'delivered', delivered_at = now()
         where id = v_item.id;

        update public.products
           set sold_count = sold_count + v_item.qty
         where id = (select product_id from public.product_variants where id = v_item.variant_id);
      else
        -- Roll back a short pick so nothing is stranded mid-order.
        if v_picked > 0 then
          update private.stock_items
             set status = 'available', order_id = null, sold_at = null
           where order_id = p_order_id
             and variant_id = v_item.variant_id
             and status = 'sold'
             and id in (select id from private.stock_items
                         where order_id = p_order_id and variant_id = v_item.variant_id
                         order by id desc limit v_picked);
        end if;

        update public.order_items
           set delivery_status = 'manual_waiting'
         where id = v_item.id;
      end if;

    elsif v_item.kind = 'manual_setup' then
      update public.order_items
         set delivery_status = 'manual_waiting'
       where id = v_item.id;

    else
      -- auto_topup: a worker calls the supplier API and flips this row.
      update public.order_items
         set delivery_status = 'pending'
       where id = v_item.id;
    end if;
  end loop;

  select
    count(*) filter (where delivery_status = 'pending'),
    count(*) filter (where delivery_status = 'manual_waiting')
    into v_pending, v_waiting
    from public.order_items where order_id = p_order_id;

  v_all_done := (v_pending = 0 and v_waiting = 0);

  update public.orders
     set status = case when v_all_done then 'delivered'::public.order_status else 'delivering'::public.order_status end,
         delivered_at = case when v_all_done then now() else delivered_at end
   where id = p_order_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- mark_order_paid: idempotent. Safe to call from a webhook more than once.
-- ---------------------------------------------------------------------------
create or replace function public.mark_order_paid(
  p_order_id     uuid,
  p_provider     public.payment_provider,
  p_provider_ref text default null,
  p_payway_method text default null,
  p_raw          jsonb default null,
  p_amount_khr   numeric default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare v_order public.orders;
begin
  select * into v_order from public.orders where id = p_order_id for update;

  if not found then
    raise exception 'order_not_found';
  end if;

  if v_order.status not in ('pending', 'paid', 'delivering') then
    return jsonb_build_object('ok', false, 'status', v_order.status);
  end if;

  if p_provider_ref is not null then
    insert into public.payments (
      order_id, provider, status, amount_usd, amount_khr,
      provider_ref, payway_method, raw_payload, verified_at
    ) values (
      p_order_id, p_provider, 'succeeded', v_order.total_usd, p_amount_khr,
      p_provider_ref, p_payway_method, p_raw, now()
    )
    on conflict (provider, provider_ref) where provider_ref is not null
    do update set status = 'succeeded', verified_at = now(), raw_payload = excluded.raw_payload;
  end if;

  if v_order.status = 'pending' then
    update public.orders set status = 'paid', paid_at = now() where id = p_order_id;

    if v_order.coupon_code is not null then
      update public.coupons
         set used_count = used_count + 1
       where upper(code) = upper(v_order.coupon_code);

      insert into public.coupon_redemptions (coupon_id, user_id, order_id, amount_usd)
      select c.id, v_order.user_id, p_order_id, v_order.discount_usd
        from public.coupons c
       where upper(c.code) = upper(v_order.coupon_code)
      on conflict do nothing;
    end if;

    perform private.deliver_order(p_order_id);
  end if;

  return jsonb_build_object('ok', true, 'status', 'paid');
end;
$$;

-- Only the service role may settle an order.
revoke execute on function public.mark_order_paid(uuid, public.payment_provider, text, text, jsonb, numeric) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Pay from wallet (debit + settle in one transaction)
-- ---------------------------------------------------------------------------
create or replace function public.pay_order_with_wallet(p_order_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user  uuid := (select auth.uid());
  v_order public.orders;
  v_bal   numeric(12, 2);
begin
  if v_user is null then raise exception 'auth_required'; end if;

  select * into v_order from public.orders
   where id = p_order_id and user_id = v_user
   for update;

  if not found then raise exception 'order_not_found'; end if;
  if v_order.status <> 'pending' then
    return jsonb_build_object('ok', false, 'status', v_order.status);
  end if;
  if v_order.expires_at < now() then raise exception 'order_expired'; end if;

  select wallet_balance into v_bal from public.profiles where id = v_user for update;
  if v_bal < v_order.total_usd then
    return jsonb_build_object('ok', false, 'reason', 'insufficient_balance', 'balance', v_bal, 'required', v_order.total_usd);
  end if;

  perform private.credit_wallet(v_user, -v_order.total_usd, 'purchase', p_order_id, 'order ' || v_order.order_no);

  update public.orders set status = 'paid', paid_at = now() where id = p_order_id;

  insert into public.payments (order_id, provider, status, amount_usd, verified_at)
  values (p_order_id, 'wallet', 'succeeded', v_order.total_usd, now());

  perform private.deliver_order(p_order_id);

  return jsonb_build_object('ok', true, 'status', 'paid');
end;
$$;

grant execute on function public.pay_order_with_wallet(uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- reveal_order: decrypted credentials for a paid order the caller owns
-- ---------------------------------------------------------------------------
create or replace function public.reveal_order(p_order_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare v_user uuid := (select auth.uid());
begin
  if v_user is null then raise exception 'auth_required'; end if;

  if not exists (
    select 1 from public.orders o
    where o.id = p_order_id
      and (o.user_id = v_user or public.is_staff())
      and o.status in ('paid', 'delivering', 'delivered')
  ) then
    raise exception 'not_authorized';
  end if;

  return (
    select coalesce(jsonb_agg(x order by x ->> 'item_id'), '[]'::jsonb)
    from (
      select jsonb_build_object(
        'item_id', oi.id,
        'product_name', oi.product_name,
        'variant_label', oi.variant_label,
        'qty', oi.qty,
        'delivery_status', oi.delivery_status,
        'payloads', (
          select coalesce(jsonb_agg(private.decrypt_payload(s.payload_enc) order by s.sold_at), '[]'::jsonb)
          from private.stock_items s
          where s.order_id = p_order_id and s.variant_id = oi.variant_id and s.status = 'sold'
        )
      ) as x
      from public.order_items oi
      where oi.order_id = p_order_id
    ) t
  );
end;
$$;

grant execute on function public.reveal_order(uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- Staff: add stock, resolve manual items, adjust wallet
-- ---------------------------------------------------------------------------
create or replace function public.admin_add_stock(p_variant_id bigint, p_payloads text[])
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare v_count integer := 0;
begin
  if not public.is_staff() then raise exception 'not_authorized'; end if;

  insert into private.stock_items (variant_id, payload_enc)
  select p_variant_id, private.encrypt_payload(p)
    from unnest(p_payloads) p
   where btrim(p) <> '';

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

grant execute on function public.admin_add_stock(bigint, text[]) to authenticated;

create or replace function public.admin_resolve_item(
  p_item_id  bigint,
  p_delivery public.delivery_status default 'delivered'
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare v_order uuid;
begin
  if not public.is_staff() then raise exception 'not_authorized'; end if;

  update public.order_items
     set delivery_status = p_delivery,
         delivered_at = case when p_delivery = 'delivered' then now() else null end
   where id = p_item_id
  returning order_id into v_order;

  if v_order is null then raise exception 'item_not_found'; end if;

  if not exists (
    select 1 from public.order_items
    where order_id = v_order and delivery_status <> 'delivered'
  ) then
    update public.orders
       set status = 'delivered', delivered_at = now()
     where id = v_order;
  end if;
end;
$$;

grant execute on function public.admin_resolve_item(bigint, public.delivery_status) to authenticated;

-- ---------------------------------------------------------------------------
-- Housekeeping: run on a schedule (pg_cron)
-- ---------------------------------------------------------------------------
create or replace function public.expire_stale_orders()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare v_count integer;
begin
  update private.stock_items
     set status = 'available', order_id = null, reserved_at = null
   where status = 'reserved'
     and reserved_at < now() - interval '30 minutes';

  with expired as (
    update public.orders
       set status = 'expired'
     where status = 'pending' and expires_at < now()
    returning id
  ),
  voided as (
    update public.payments p
       set status = 'expired'
      from expired e
     where p.order_id = e.id and p.status in ('initiated', 'pending')
    returning p.id
  )
  select count(*) into v_count from expired;

  return v_count;
end;
$$;

create or replace function public.refresh_product_ratings()
returns void
language sql
security definer
set search_path = ''
as $$
  update public.products p
     set rating_avg = coalesce(r.avg_rating, 0),
         rating_count = coalesce(r.cnt, 0)
    from (
      select product_id, round(avg(rating)::numeric, 2) as avg_rating, count(*) as cnt
        from public.reviews
       where is_approved
       group by product_id
    ) r
   where p.id = r.product_id;
$$;


-- ============================================================================
-- 20261015000400_wallet_cron_admin.sql
-- ============================================================================

do $$ begin raise notice '>>> 20261015000400_wallet_cron_admin.sql'; end $$;

-- ============================================================================
-- Closes the gaps found in the first audit:
--   1. wallet had no way to be funded
--   2. expire_stale_orders() and refresh_product_ratings() were never scheduled
--   3. reviews could never be approved, so ratings stayed at zero
--   4. auto_topup items had no worker to fulfil them
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. Wallet top-up
--
-- A top-up reuses the whole order/payment pipeline: create a pending order with
-- kind='wallet_topup', pay it by KHQR, and mark_order_paid credits the wallet
-- instead of delivering goods.
-- ---------------------------------------------------------------------------
alter table public.orders
  add column if not exists kind text not null default 'purchase'
  check (kind in ('purchase', 'wallet_topup'));

create index if not exists orders_kind_idx on public.orders (kind) where kind = 'wallet_topup';

alter table public.settings
  add column if not exists topup_min_usd numeric(12, 2) not null default 1,
  add column if not exists topup_max_usd numeric(12, 2) not null default 1000;

create or replace view public.public_settings as
select
  id,
  site_name,
  support_telegram,
  support_email,
  usd_to_khr,
  order_ttl_minutes,
  khqr_account_id,
  khqr_merchant_name,
  khqr_merchant_city,
  is_maintenance,
  topup_min_usd,
  topup_max_usd
from public.settings;

grant select on public.public_settings to anon, authenticated;

create or replace function public.create_wallet_topup(
  p_amount_usd numeric,
  p_email      text default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user     uuid := (select auth.uid());
  v_profile  public.profiles;
  v_settings public.settings;
  v_order_id uuid;
  v_order_no text;
begin
  if v_user is null then
    raise exception 'auth_required';
  end if;

  select * into v_profile from public.profiles where id = v_user;
  if v_profile.is_blocked then
    raise exception 'account_blocked';
  end if;

  select * into v_settings from public.settings where id;

  -- Round to cents so the KHQR amount always matches what PayWay is told.
  p_amount_usd := round(coalesce(p_amount_usd, 0), 2);

  if p_amount_usd < v_settings.topup_min_usd then
    raise exception 'topup_below_minimum'
      using detail = v_settings.topup_min_usd::text;
  end if;

  if p_amount_usd > v_settings.topup_max_usd then
    raise exception 'topup_above_maximum'
      using detail = v_settings.topup_max_usd::text;
  end if;

  v_order_no := private.new_order_no();

  insert into public.orders (
    order_no, user_id, status, kind, contact_email,
    subtotal_usd, discount_usd, total_usd, expires_at
  ) values (
    v_order_no, v_user, 'pending', 'wallet_topup', p_email,
    p_amount_usd, 0, p_amount_usd,
    now() + make_interval(mins => v_settings.order_ttl_minutes)
  ) returning id into v_order_id;

  return jsonb_build_object(
    'order_id', v_order_id,
    'order_no', v_order_no,
    'total_usd', p_amount_usd,
    'expires_in_minutes', v_settings.order_ttl_minutes
  );
end;
$$;

grant execute on function public.create_wallet_topup(numeric, text) to authenticated;

-- ---------------------------------------------------------------------------
-- mark_order_paid: credit top-ups instead of delivering goods
-- ---------------------------------------------------------------------------
create or replace function public.mark_order_paid(
  p_order_id      uuid,
  p_provider      public.payment_provider,
  p_provider_ref  text default null,
  p_payway_method text default null,
  p_raw           jsonb default null,
  p_amount_khr    numeric default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_order public.orders;
  v_bal   numeric(12, 2);
begin
  select * into v_order from public.orders where id = p_order_id for update;

  if not found then
    raise exception 'order_not_found';
  end if;

  if v_order.status not in ('pending', 'paid', 'delivering', 'delivered') then
    return jsonb_build_object('ok', false, 'status', v_order.status);
  end if;

  if p_provider_ref is not null then
    insert into public.payments (
      order_id, provider, status, amount_usd, amount_khr,
      provider_ref, payway_method, raw_payload, verified_at
    ) values (
      p_order_id, p_provider, 'succeeded', v_order.total_usd, p_amount_khr,
      p_provider_ref, p_payway_method, p_raw, now()
    )
    on conflict (provider, provider_ref) where provider_ref is not null
    do update set status = 'succeeded', verified_at = now(), raw_payload = excluded.raw_payload;
  end if;

  -- Idempotency: only the transition out of 'pending' moves money or stock.
  if v_order.status = 'pending' then
    update public.orders set status = 'paid', paid_at = now() where id = p_order_id;

    if v_order.coupon_code is not null then
      update public.coupons
         set used_count = used_count + 1
       where upper(code) = upper(v_order.coupon_code);

      insert into public.coupon_redemptions (coupon_id, user_id, order_id, amount_usd)
      select c.id, v_order.user_id, p_order_id, v_order.discount_usd
        from public.coupons c
       where upper(c.code) = upper(v_order.coupon_code)
      on conflict do nothing;
    end if;

    if v_order.kind = 'wallet_topup' then
      v_bal := private.credit_wallet(
        v_order.user_id, v_order.total_usd, 'topup', p_order_id,
        'topup ' || v_order.order_no
      );

      update public.orders
         set status = 'delivered', delivered_at = now()
       where id = p_order_id;

      return jsonb_build_object('ok', true, 'status', 'delivered', 'wallet_balance', v_bal);
    end if;

    perform private.deliver_order(p_order_id);
  end if;

  return jsonb_build_object('ok', true, 'status', 'paid');
end;
$$;

revoke execute on function public.mark_order_paid(uuid, public.payment_provider, text, text, jsonb, numeric)
  from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- 2 + 3. Review approval, and ratings that actually move
-- ---------------------------------------------------------------------------
create or replace function public.admin_review_set_approved(
  p_review_id bigint,
  p_approved  boolean,
  p_reward_coins integer default 5
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare v_review public.reviews;
begin
  if not public.is_staff() then
    raise exception 'not_authorized';
  end if;

  update public.reviews
     set is_approved = p_approved
   where id = p_review_id
  returning * into v_review;

  if not found then
    raise exception 'review_not_found';
  end if;

  -- Pay the review reward once, and only for an approval.
  if p_approved and not v_review.coin_rewarded and p_reward_coins > 0 then
    update public.profiles
       set coins = coins + p_reward_coins
     where id = v_review.user_id;

    update public.reviews set coin_rewarded = true where id = p_review_id;
  end if;

  perform public.refresh_product_ratings();
end;
$$;

grant execute on function public.admin_review_set_approved(bigint, boolean, integer) to authenticated;

-- Rating drift is otherwise silent, so keep it refresher-driven.
create or replace function public.refresh_all_product_ratings()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare v_count integer;
begin
  update public.products p
     set rating_avg = coalesce(r.avg_rating, 0),
         rating_count = coalesce(r.cnt, 0)
    from (
      select product_id,
             round(avg(rating)::numeric, 2) as avg_rating,
             count(*)                        as cnt
        from public.reviews
       where is_approved
       group by product_id
    ) r
   where p.id = r.product_id;

  get diagnostics v_count = row_count;

  -- Products whose last review was unapproved keep a stale average; zero them.
  update public.products p
     set rating_avg = 0, rating_count = 0
   where not exists (
     select 1 from public.reviews rv
      where rv.product_id = p.id and rv.is_approved
   )
     and (p.rating_avg <> 0 or p.rating_count <> 0);

  return v_count;
end;
$$;

-- ---------------------------------------------------------------------------
-- 4. Supplier worker: hand out auto_topup lines and take them back
-- ---------------------------------------------------------------------------
create or replace function public.supplier_pending_items(p_limit integer default 20)
returns table (
  item_id        bigint,
  order_id       uuid,
  order_no       text,
  variant_id     bigint,
  sku            text,
  qty            integer,
  customer_fields jsonb,
  supplier_code  text,
  supplier_sku   text,
  cost_usd       numeric
)
language sql
stable
security definer
set search_path = ''
as $$
  select
    oi.id,
    o.id,
    o.order_no,
    v.id,
    v.sku,
    oi.qty,
    o.customer_fields,
    s.code,
    ss.supplier_sku,
    coalesce(ss.cost_usd, v.cost_usd)
  from public.order_items oi
  join public.orders o on o.id = oi.order_id
  join public.product_variants v on v.id = oi.variant_id
  join public.products p on p.id = v.product_id
  left join public.supplier_skus ss on ss.variant_id = v.id and ss.is_active
  left join public.suppliers s on s.id = ss.supplier_id and s.is_active
 where oi.delivery_status = 'pending'
   and p.kind = 'auto_topup'
   and o.status in ('paid', 'delivering')
 order by oi.id
 limit p_limit;
$$;

revoke execute on function public.supplier_pending_items(integer) from public, anon, authenticated;

create or replace function public.supplier_complete_item(
  p_item_id   bigint,
  p_success   boolean,
  p_supplier_ref text default null,
  p_cost_usd  numeric default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_item    public.order_items;
  v_order   public.orders;
  v_pending integer;
  v_failed  integer;
begin
  select * into v_item from public.order_items where id = p_item_id for update;
  if not found then
    raise exception 'item_not_found';
  end if;

  select * into v_order from public.orders where id = v_item.order_id for update;

  if p_success then
    update public.order_items
       set delivery_status = 'delivered',
           delivered_at = now(),
           supplier_ref = coalesce(p_supplier_ref, supplier_ref),
           unit_cost_usd = coalesce(p_cost_usd, unit_cost_usd)
     where id = p_item_id;

    update public.products
       set sold_count = sold_count + v_item.qty
     where id = (select product_id from public.product_variants where id = v_item.variant_id);
  else
    update public.order_items
       set delivery_status = 'failed',
           supplier_ref = coalesce(p_supplier_ref, supplier_ref)
     where id = p_item_id;

    -- The buyer paid for something we cannot deliver, so return it to their
    -- wallet rather than leaving them to open a support ticket.
    perform private.credit_wallet(
      v_order.user_id, v_item.line_total_usd, 'refund', v_order.id,
      'refund ' || v_order.order_no || ' (' || v_item.product_name || ')'
    );
  end if;

  select
    count(*) filter (where delivery_status = 'pending'),
    count(*) filter (where delivery_status = 'failed')
    into v_pending, v_failed
    from public.order_items where order_id = v_order.id;

  if v_pending = 0 then
    update public.orders
       set status = case
                      when v_failed > 0 then 'failed'::public.order_status
                      else 'delivered'::public.order_status
                    end,
           delivered_at = case when v_failed = 0 then now() else delivered_at end
     where id = v_order.id;
  end if;

  return jsonb_build_object(
    'ok', true,
    'order_status', (select status from public.orders where id = v_order.id),
    'refunded_usd', case when p_success then 0 else v_item.line_total_usd end
  );
end;
$$;

revoke execute on function public.supplier_complete_item(bigint, boolean, text, numeric)
  from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- 2 (cont). Schedule the housekeeping that was never running
--
-- This block must never fail the migration. Scheduling housekeeping is a nice
-- to have; creating the schema is not. On hosted Supabase cron.job is owned by
-- supabase_admin, so direct DML is refused and you must use cron.unschedule().
-- Each step is wrapped so a permission problem degrades to a notice.
-- ---------------------------------------------------------------------------
do $$
declare
  v_have_cron boolean := exists (select 1 from pg_namespace where nspname = 'cron');
begin
  if not v_have_cron then
    begin
      if exists (select 1 from pg_available_extensions where name = 'pg_cron') then
        execute 'create extension pg_cron';
        v_have_cron := true;
      end if;
    exception when others then
      raise notice 'pg_cron could not be installed here (%); schedule manually', sqlerrm;
    end;
  end if;

  if not v_have_cron then
    raise notice 'pg_cron unavailable; schedule expire_stale_orders() and refresh_all_product_ratings() on the host';
    return;
  end if;

  -- Unschedule by name via the API, never by touching cron.job.
  begin
    perform cron.unschedule('ycp-expire-orders');
  exception when others then null;
  end;

  begin
    perform cron.unschedule('ycp-refresh-ratings');
  exception when others then null;
  end;

  begin
    perform cron.schedule('ycp-expire-orders', '*/2 * * * *',
                          'select public.expire_stale_orders()');
    perform cron.schedule('ycp-refresh-ratings', '*/30 * * * *',
                          'select public.refresh_all_product_ratings()');
    raise notice 'pg_cron jobs scheduled';
  exception
    when insufficient_privilege then
      raise notice 'pg_cron present but not schedulable by this role (%); schedule manually', sqlerrm;
    when others then
      raise notice 'pg_cron scheduling skipped: %', sqlerrm;
  end;
end $$;

-- ---------------------------------------------------------------------------
-- Housekeeping: also void expired top-ups, and expose the sweep to staff
-- ---------------------------------------------------------------------------
create or replace function public.admin_run_housekeeping()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare v_expired integer;
begin
  if not public.is_staff() then
    raise exception 'not_authorized';
  end if;

  v_expired := public.expire_stale_orders();
  perform public.refresh_all_product_ratings();

  return jsonb_build_object('expired_orders', v_expired);
end;
$$;

grant execute on function public.admin_run_housekeeping() to authenticated;


-- ============================================================================
-- 20261015000500_telegram.sql
-- ============================================================================

do $$ begin raise notice '>>> 20261015000500_telegram.sql'; end $$;

-- ============================================================================
-- Telegram: account linking, and an outbox so notifications are durable.
--
-- Why an outbox rather than sending directly: an instant order is delivered
-- inside mark_order_paid, but a manual or supplier order is delivered minutes
-- or hours later by a different actor. Writing the message to a table means the
-- notification cannot be lost if the sender is not around at that moment.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Settings the bot needs
-- ---------------------------------------------------------------------------
alter table public.settings
  add column if not exists telegram_bot_username text,
  add column if not exists support_telegram_chat_id bigint;

create or replace view public.public_settings as
select
  id, site_name, support_telegram, support_email, usd_to_khr, order_ttl_minutes,
  khqr_account_id, khqr_merchant_name, khqr_merchant_city, is_maintenance,
  topup_min_usd, topup_max_usd, telegram_bot_username
from public.settings;

grant select on public.public_settings to anon, authenticated;

-- ---------------------------------------------------------------------------
-- Linking
-- ---------------------------------------------------------------------------
alter table public.profiles
  add column if not exists telegram_chat_id bigint,
  add column if not exists telegram_username text,
  add column if not exists telegram_linked_at timestamptz;

create unique index if not exists profiles_telegram_chat_idx
  on public.profiles (telegram_chat_id) where telegram_chat_id is not null;

create table if not exists public.telegram_link_codes (
  code       text primary key,
  user_id    uuid not null references public.profiles (id) on delete cascade,
  expires_at timestamptz not null default (now() + interval '15 minutes'),
  used_at    timestamptz,
  created_at timestamptz not null default now()
);

alter table public.telegram_link_codes enable row level security;
-- No policies and no grants: reached only through the functions below.

-- ---------------------------------------------------------------------------
-- Outbox
-- ---------------------------------------------------------------------------
create table if not exists public.notifications (
  id         bigint generated always as identity primary key,
  user_id    uuid references public.profiles (id) on delete cascade,
  chat_id    bigint,
  kind       text not null,
  payload    jsonb not null default '{}'::jsonb,
  status     text not null default 'pending'
             check (status in ('pending', 'sending', 'sent', 'failed', 'skipped')),
  attempts   integer not null default 0,
  last_error text,
  created_at timestamptz not null default now(),
  sent_at    timestamptz
);

alter table public.notifications enable row level security;

create index if not exists notifications_pending_idx
  on public.notifications (created_at) where status = 'pending';

create index if not exists notifications_user_idx
  on public.notifications (user_id, created_at desc);

-- ---------------------------------------------------------------------------
-- Enqueue on terminal order states.
--
-- Deliberately only 'delivered' and 'failed': notifying on 'paid' would fire a
-- second message milliseconds later for instant orders, and 'delivering' means
-- nothing to the buyer yet.
-- ---------------------------------------------------------------------------
create or replace function private.enqueue_order_notification()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare v_chat bigint;
begin
  if new.status = old.status then
    return new;
  end if;

  if new.status not in ('delivered', 'failed') then
    return new;
  end if;

  select p.telegram_chat_id into v_chat
    from public.profiles p where p.id = new.user_id;

  insert into public.notifications (user_id, chat_id, kind, payload)
  values (
    new.user_id,
    v_chat,
    case new.status
      when 'delivered' then 'order_delivered'
      else 'order_failed'
    end,
    jsonb_build_object(
      'order_id', new.id,
      'order_no', new.order_no,
      'total_usd', new.total_usd,
      'kind', new.kind
    )
  );

  return new;
end;
$$;

drop trigger if exists orders_notify on public.orders;
create trigger orders_notify
  after update on public.orders
  for each row execute function private.enqueue_order_notification();

-- ---------------------------------------------------------------------------
-- create_telegram_link_code: the app shows a code, the buyer sends it to the bot
-- ---------------------------------------------------------------------------
create or replace function public.create_telegram_link_code()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user   uuid := (select auth.uid());
  v_code   text;
  v_bot    text;
begin
  if v_user is null then
    raise exception 'auth_required';
  end if;

  -- One live code per user.
  delete from public.telegram_link_codes
   where user_id = v_user and used_at is null;

  v_code := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 6));

  insert into public.telegram_link_codes (code, user_id) values (v_code, v_user);

  select telegram_bot_username into v_bot from public.settings where id;

  return jsonb_build_object(
    'code', v_code,
    'expires_in_minutes', 15,
    'bot_username', v_bot,
    'deep_link', case
      when v_bot is null then null
      else 'https://t.me/' || v_bot || '?start=' || v_code
    end
  );
end;
$$;

grant execute on function public.create_telegram_link_code() to authenticated;

-- ---------------------------------------------------------------------------
-- link_telegram: called by the webhook after /start <code>
-- ---------------------------------------------------------------------------
create or replace function public.link_telegram(
  p_code     text,
  p_chat_id  bigint,
  p_username text default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare v_row public.telegram_link_codes;
begin
  select * into v_row
    from public.telegram_link_codes
   where code = upper(btrim(p_code))
     and used_at is null
   for update;

  if not found then
    return jsonb_build_object('ok', false, 'reason', 'code_invalid');
  end if;

  if v_row.expires_at < now() then
    return jsonb_build_object('ok', false, 'reason', 'code_expired');
  end if;

  -- A Telegram account belongs to one profile at a time.
  update public.profiles
     set telegram_chat_id = null, telegram_username = null, telegram_linked_at = null
   where telegram_chat_id = p_chat_id and id <> v_row.user_id;

  update public.profiles
     set telegram_chat_id = p_chat_id,
         telegram_username = p_username,
         telegram_linked_at = now()
   where id = v_row.user_id;

  update public.telegram_link_codes set used_at = now() where code = v_row.code;

  return jsonb_build_object('ok', true, 'user_id', v_row.user_id);
end;
$$;

revoke execute on function public.link_telegram(text, bigint, text)
  from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Outbox claim / ack, used by the dispatcher
-- ---------------------------------------------------------------------------
create or replace function public.telegram_claim_notifications(p_limit integer default 20)
returns table (
  notification_id bigint,
  chat_id         bigint,
  kind            text,
  payload         jsonb
)
language plpgsql
security definer
set search_path = ''
as $$
begin
  -- Resolve the chat at send time rather than at enqueue time. A buyer who
  -- links their account after an order was delivered still gets the message.
  update public.notifications n
     set chat_id = p.telegram_chat_id
    from public.profiles p
   where n.user_id = p.id
     and n.status = 'pending'
     and n.chat_id is null
     and p.telegram_chat_id is not null;

  -- Give an unlinked buyer a day to link before writing the message off.
  -- Notifications stay in the app either way.
  update public.notifications n
     set status = 'skipped', last_error = 'no_telegram_account'
   where n.status = 'pending'
     and n.chat_id is null
     and n.created_at < now() - interval '24 hours';

  -- Anything stuck in 'sending' means a dispatcher died mid-flight.
  update public.notifications n
     set status = 'pending', last_error = 'requeued_after_timeout'
   where n.status = 'sending' and n.attempts < 5;

  return query
  with claimed as (
    select n2.id
      from public.notifications n2
     where n2.status = 'pending'
       and n2.chat_id is not null
       and n2.attempts < 5
     order by n2.created_at
     limit p_limit
     for update skip locked
  )
  update public.notifications n3
     set status = 'sending', attempts = n3.attempts + 1
    from claimed c
   where n3.id = c.id
  returning n3.id, n3.chat_id, n3.kind, n3.payload;
end;
$$;

revoke execute on function public.telegram_claim_notifications(integer)
  from public, anon, authenticated;

create or replace function public.telegram_ack_notification(
  p_id     bigint,
  p_ok     boolean,
  p_error  text default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.notifications
     set status = case
                    when p_ok then 'sent'
                    when attempts >= 5 then 'failed'
                    else 'pending'
                  end,
         last_error = p_error,
         sent_at = case when p_ok then now() else sent_at end
   where id = p_id;
end;
$$;

revoke execute on function public.telegram_ack_notification(bigint, boolean, text)
  from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- What the bot is allowed to read back to a chat
-- ---------------------------------------------------------------------------
create or replace function public.telegram_orders_for_chat(
  p_chat_id bigint,
  p_limit   integer default 5
)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(x), '[]'::jsonb)
  from (
    select jsonb_build_object(
      'order_no', o.order_no,
      'status', o.status,
      'total_usd', o.total_usd,
      'created_at', o.created_at,
      'items', (
        select coalesce(jsonb_agg(oi.product_name || ' x' || oi.qty), '[]'::jsonb)
          from public.order_items oi where oi.order_id = o.id
      )
    ) as x
    from public.orders o
    join public.profiles p on p.id = o.user_id
   where p.telegram_chat_id = p_chat_id
   order by o.created_at desc
   limit p_limit
  ) t;
$$;

revoke execute on function public.telegram_orders_for_chat(bigint, integer)
  from public, anon, authenticated;

create or replace function public.telegram_order_by_no(
  p_chat_id  bigint,
  p_order_no text
)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'order_no', o.order_no,
    'status', o.status,
    'total_usd', o.total_usd,
    'created_at', o.created_at,
    'items', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'name', oi.product_name,
        'qty', oi.qty,
        'delivery_status', oi.delivery_status,
        'codes', coalesce((
          select jsonb_agg(private.decrypt_payload(s.payload_enc) order by s.sold_at)
            from private.stock_items s
           where s.order_id = o.id and s.variant_id = oi.variant_id and s.status = 'sold'
        ), '[]'::jsonb)
      )), '[]'::jsonb)
      from public.order_items oi where oi.order_id = o.id
    )
  )
  from public.orders o
  join public.profiles p on p.id = o.user_id
 where p.telegram_chat_id = p_chat_id
   and upper(o.order_no) = upper(btrim(p_order_no))
   and o.status in ('paid', 'delivering', 'delivered')
  limit 1;
$$;

revoke execute on function public.telegram_order_by_no(bigint, text)
  from public, anon, authenticated;

create or replace function public.telegram_profile_for_chat(p_chat_id bigint)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'user_id', p.id,
    'display_name', p.display_name,
    'wallet_balance', p.wallet_balance,
    'coins', p.coins,
    'linked_at', p.telegram_linked_at
  )
  from public.profiles p
  where p.telegram_chat_id = p_chat_id
  limit 1;
$$;

revoke execute on function public.telegram_profile_for_chat(bigint)
  from public, anon, authenticated;

create or replace function public.telegram_unlink(p_chat_id bigint)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare v_count integer;
begin
  update public.profiles
     set telegram_chat_id = null, telegram_username = null, telegram_linked_at = null
   where telegram_chat_id = p_chat_id;

  get diagnostics v_count = row_count;
  return v_count > 0;
end;
$$;

revoke execute on function public.telegram_unlink(bigint)
  from public, anon, authenticated;


-- ============================================================================
-- 20261015000600_suppliers.sql
-- ============================================================================

do $$ begin raise notice '>>> 20261015000600_suppliers.sql'; end $$;

-- ============================================================================
-- Supplier integration: make sync and fulfilment idempotent, and let a line
-- defer (retry) instead of being refunded when the failure is ours, not the
-- buyer's.
--
-- The distinction matters: "insufficient supplier balance" must not refund a
-- buyer who paid correctly, and must not silently drop the order either.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Products owned by a supplier sync
-- ---------------------------------------------------------------------------
alter table public.products
  add column if not exists supplier_id bigint references public.suppliers (id) on delete set null,
  add column if not exists supplier_game_code text;

create unique index if not exists products_supplier_game_idx
  on public.products (supplier_id, supplier_game_code)
  where supplier_id is not null and supplier_game_code is not null;

-- ---------------------------------------------------------------------------
-- Attempt tracking on the job row
-- ---------------------------------------------------------------------------
alter table public.order_items
  add column if not exists supplier_attempts integer not null default 0,
  add column if not exists supplier_last_error text,
  add column if not exists supplier_next_attempt_at timestamptz;

-- ---------------------------------------------------------------------------
-- Known suppliers. is_active stays false until a key exists.
-- ---------------------------------------------------------------------------
insert into public.suppliers (code, name, base_url, is_active) values
  ('bay2game', 'Bay2Game', 'https://api.bay2game.xyz/api', false),
  ('kasplay',  'KAS Play', 'https://reseller-api.kasplay.kascambodia.com/api/v1', false)
on conflict (code) do nothing;

-- ---------------------------------------------------------------------------
-- supplier_pending_items: skip lines that are backing off or exhausted, and
-- hand the worker everything it needs including attempt count.
-- ---------------------------------------------------------------------------
drop function if exists public.supplier_pending_items(integer);

create or replace function public.supplier_pending_items(p_limit integer default 20)
returns table (
  item_id         bigint,
  order_id        uuid,
  order_no        text,
  variant_id      bigint,
  sku             text,
  qty             integer,
  customer_fields jsonb,
  supplier_code   text,
  supplier_sku    text,
  cost_usd        numeric,
  attempts        integer
)
language sql
stable
security definer
set search_path = ''
as $$
  select
    oi.id,
    o.id,
    o.order_no,
    v.id,
    v.sku,
    oi.qty,
    o.customer_fields,
    s.code,
    ss.supplier_sku,
    coalesce(ss.cost_usd, v.cost_usd),
    oi.supplier_attempts
  from public.order_items oi
  join public.orders o on o.id = oi.order_id
  join public.product_variants v on v.id = oi.variant_id
  join public.products p on p.id = v.product_id
  left join public.supplier_skus ss on ss.variant_id = v.id and ss.is_active
  left join public.suppliers s on s.id = ss.supplier_id and s.is_active
 where oi.delivery_status = 'pending'
   and p.kind = 'auto_topup'
   and o.status in ('paid', 'delivering')
   and oi.supplier_attempts < 5
   and (oi.supplier_next_attempt_at is null or oi.supplier_next_attempt_at <= now())
 order by oi.id
 limit p_limit;
$$;

revoke execute on function public.supplier_pending_items(integer)
  from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- supplier_note_failure: record an attempt without moving money.
-- Used when the failure is transient or the supplier account is at fault
-- (out of balance, upstream 500). The line stays pending and retries.
-- ---------------------------------------------------------------------------
create or replace function public.supplier_note_failure(
  p_item_id bigint,
  p_error   text,
  p_retry_in_minutes integer default 10
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare v_attempts integer;
begin
  update public.order_items
     set supplier_attempts = supplier_attempts + 1,
         supplier_last_error = left(p_error, 500),
         supplier_next_attempt_at = now() + make_interval(mins => p_retry_in_minutes)
   where id = p_item_id
  returning supplier_attempts into v_attempts;

  if not found then
    raise exception 'item_not_found';
  end if;

  -- Out of retries: this is now a staff problem, so leave a marker rather than
  -- refunding a buyer whose order was never actually attempted.
  if v_attempts >= 5 then
    update public.order_items
       set delivery_status = 'manual_waiting'
     where id = p_item_id;
  end if;

  return jsonb_build_object('ok', true, 'attempts', v_attempts);
end;
$$;

revoke execute on function public.supplier_note_failure(bigint, text, integer)
  from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- supplier_upsert_catalogue: one call per game, so a sync is atomic per game
-- and cannot leave a half-linked product behind.
-- ---------------------------------------------------------------------------
create or replace function public.supplier_upsert_catalogue(
  p_supplier_code text,
  p_game_code     text,
  p_name          text,
  p_image_url     text,
  p_summary       text,
  p_required_fields jsonb,      -- ["userid","serverid"]
  p_products      jsonb         -- [{ product_code, name, price_usd }]
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_supplier public.suppliers;
  v_product_id bigint;
  v_slug text;
  v_item jsonb;
  v_variant_id bigint;
  v_upserted integer := 0;
begin
  select * into v_supplier from public.suppliers where code = p_supplier_code;
  if not found then
    raise exception 'unknown_supplier' using detail = p_supplier_code;
  end if;

  v_slug := p_supplier_code || '-' || p_game_code;

  insert into public.products (
    slug, name_km, name_en, summary_km, summary_en, image_url, kind,
    requires_fields, supplier_id, supplier_game_code, is_active, sort_order
  ) values (
    v_slug, p_name, p_name, p_summary, p_summary, p_image_url, 'auto_topup',
    coalesce(p_required_fields, '[]'::jsonb), v_supplier.id, p_game_code, true, 1000
  )
  on conflict (slug) do update
    set name_km       = excluded.name_km,
        name_en       = excluded.name_en,
        summary_km    = excluded.summary_km,
        summary_en    = excluded.summary_en,
        image_url     = coalesce(excluded.image_url, public.products.image_url),
        requires_fields = excluded.requires_fields,
        supplier_id   = excluded.supplier_id,
        supplier_game_code = excluded.supplier_game_code,
        updated_at    = now()
  returning id into v_product_id;

  for v_item in select * from jsonb_array_elements(p_products)
  loop
    insert into public.product_variants (
      product_id, sku, label_km, label_en, price_usd, cost_usd,
      stock_mode, min_qty, max_qty, is_active, sort_order
    ) values (
      v_product_id,
      (v_item ->> 'product_code'),
      (v_item ->> 'name'),
      (v_item ->> 'name'),
      -- The supplier price is cost. Retail is set by staff afterwards; until
      -- then it is cost, so an unpriced SKU can never be sold at a loss.
      round((v_item ->> 'price_usd')::numeric, 2),
      round((v_item ->> 'price_usd')::numeric, 2),
      'unlimited', 1, 50, true, coalesce((v_item ->> 'sort')::int, 0)
    )
    on conflict (sku) do update
      set label_km  = excluded.label_km,
          label_en  = excluded.label_en,
          cost_usd  = excluded.cost_usd,
          is_active = true,
          product_id = excluded.product_id
    returning id into v_variant_id;

    insert into public.supplier_skus (
      supplier_id, variant_id, supplier_sku, cost_usd, is_active, last_synced_at, last_cost_usd
    ) values (
      v_supplier.id, v_variant_id, (v_item ->> 'product_code'),
      round((v_item ->> 'price_usd')::numeric, 2), true, now(),
      round((v_item ->> 'price_usd')::numeric, 2)
    )
    on conflict (supplier_id, variant_id, supplier_sku) do update
      set cost_usd       = excluded.cost_usd,
          last_cost_usd  = excluded.last_cost_usd,
          last_synced_at = now(),
          is_active      = true;

    v_upserted := v_upserted + 1;
  end loop;

  return jsonb_build_object(
    'product_id', v_product_id,
    'slug', v_slug,
    'variants_synced', v_upserted
  );
end;
$$;

revoke execute on function public.supplier_upsert_catalogue(text, text, text, text, text, jsonb, jsonb)
  from public, anon, authenticated;


-- ============================================================================
-- 20261015000700_supplier_field_definitions.sql
-- ============================================================================

do $$ begin raise notice '>>> 20261015000700_supplier_field_definitions.sql'; end $$;

-- ============================================================================
-- Supplier buyer fields must be field DEFINITIONS, not bare names.
--
-- `20261015000600_suppliers.sql` stored a game's `game_fields` verbatim, so a
-- Bay2Game product ended up with:
--
--   requires_fields = ["userid","serverid"]
--
-- Every other part of the system expects the object shape the seeds use:
--
--   [{"key":"userid","label_km":"...","label_en":"Game ID",...}]
--
--   - the app reads `key`, `label_km`, `label_en` off each entry
--     (`RequiredField.fromJson`), and `catalog_repository.dart` casts each one
--     to a Map, so a bare string threw and the whole product page failed.
--   - `create_order` resolves the missing-field list with `f ->> 'key'`, which
--     is NULL for a string entry, so `string_agg` returned NULL and the check
--     was skipped entirely. The order went through with no game id, the buyer
--     paid, and the adapter then refunded `missing_game_user_id`.
--
-- Normalise on write, tolerate both shapes on input, and repair rows already
-- synced by the old code.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- supplier_field_definitions: coerce a game's field list into definitions.
--
-- Accepts ["userid", ...] and [{"key":"userid", ...}, ...] so an adapter that
-- carries no label metadata still produces a renderable field, and so the
-- previous shape keeps working. Missing labels fall back to the key. Entries
-- with no resolvable key are dropped rather than stored unusable.
-- ---------------------------------------------------------------------------
create or replace function public.supplier_field_definitions(p_fields jsonb)
returns jsonb
language sql
immutable
set search_path = ''
as $$
  select coalesce(jsonb_agg(entry order by ord), '[]'::jsonb)
  from (
    select
      case
        when jsonb_typeof(f.elem) = 'string' then
          jsonb_build_object(
            'key', f.elem #>> '{}',
            'label_km', f.elem #>> '{}',
            'label_en', f.elem #>> '{}'
          )
        else
          -- Strip nulls first so a null placeholder is absent, not present-null.
          jsonb_strip_nulls(f.elem)
            || jsonb_build_object(
                 'label_km', coalesce(nullif(f.elem ->> 'label_km', ''), f.elem ->> 'key'),
                 'label_en', coalesce(nullif(f.elem ->> 'label_en', ''), f.elem ->> 'key')
               )
      end as entry,
      f.ord
    from jsonb_array_elements(
      case when jsonb_typeof(p_fields) = 'array' then p_fields else '[]'::jsonb end
    ) with ordinality as f(elem, ord)
    where coalesce(
            case
              when jsonb_typeof(f.elem) = 'string' then f.elem #>> '{}'
              else f.elem ->> 'key'
            end, ''
          ) <> ''
  ) s;
$$;

revoke execute on function public.supplier_field_definitions(jsonb)
  from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Repair products the old sync already wrote with bare field names.
-- ---------------------------------------------------------------------------
update public.products
   set requires_fields = public.supplier_field_definitions(requires_fields),
       updated_at = now()
 where jsonb_typeof(requires_fields) = 'array'
   and exists (
     select 1 from jsonb_array_elements(requires_fields) f
      where jsonb_typeof(f) = 'string'
   );

-- ---------------------------------------------------------------------------
-- supplier_upsert_catalogue: same contract, normalised fields.
-- ---------------------------------------------------------------------------
create or replace function public.supplier_upsert_catalogue(
  p_supplier_code text,
  p_game_code     text,
  p_name          text,
  p_image_url     text,
  p_summary       text,
  p_required_fields jsonb,      -- ["userid","serverid"] or [{ key, label_km, label_en }]
  p_products      jsonb         -- [{ product_code, name, price_usd }]
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_supplier public.suppliers;
  v_product_id bigint;
  v_slug text;
  v_item jsonb;
  v_variant_id bigint;
  v_fields jsonb;
  v_upserted integer := 0;
begin
  select * into v_supplier from public.suppliers where code = p_supplier_code;
  if not found then
    raise exception 'unknown_supplier' using detail = p_supplier_code;
  end if;

  v_slug := p_supplier_code || '-' || p_game_code;
  v_fields := public.supplier_field_definitions(p_required_fields);

  insert into public.products (
    slug, name_km, name_en, summary_km, summary_en, image_url, kind,
    requires_fields, supplier_id, supplier_game_code, is_active, sort_order
  ) values (
    v_slug, p_name, p_name, p_summary, p_summary, p_image_url, 'auto_topup',
    v_fields, v_supplier.id, p_game_code, true, 1000
  )
  on conflict (slug) do update
    set name_km       = excluded.name_km,
        name_en       = excluded.name_en,
        summary_km    = excluded.summary_km,
        summary_en    = excluded.summary_en,
        image_url     = coalesce(excluded.image_url, public.products.image_url),
        requires_fields = excluded.requires_fields,
        supplier_id   = excluded.supplier_id,
        supplier_game_code = excluded.supplier_game_code,
        updated_at    = now()
  returning id into v_product_id;

  for v_item in select * from jsonb_array_elements(p_products)
  loop
    -- Name the failure. A product payload whose key does not match
    -- `product_code` used to surface as a product_variants.sku not-null
    -- violation, which says nothing about the caller being wrong.
    if coalesce(btrim(v_item ->> 'product_code'), '') = '' then
      raise exception 'product_missing_code'
        using detail = left(v_item::text, 200);
    end if;

    insert into public.product_variants (
      product_id, sku, label_km, label_en, price_usd, cost_usd,
      stock_mode, min_qty, max_qty, is_active, sort_order
    ) values (
      v_product_id,
      (v_item ->> 'product_code'),
      (v_item ->> 'name'),
      (v_item ->> 'name'),
      -- The supplier price is cost. Retail is set by staff afterwards; until
      -- then it is cost, so an unpriced SKU can never be sold at a loss.
      round((v_item ->> 'price_usd')::numeric, 2),
      round((v_item ->> 'price_usd')::numeric, 2),
      'unlimited', 1, 50, true, coalesce((v_item ->> 'sort')::int, 0)
    )
    on conflict (sku) do update
      set label_km   = excluded.label_km,
          label_en   = excluded.label_en,
          cost_usd   = excluded.cost_usd,
          -- The supplier's list order is the display order. Leaving this out
          -- froze the first sync's ordering forever, so a re-sync could never
          -- correct a pack that moved.
          sort_order = excluded.sort_order,
          is_active  = true,
          product_id = excluded.product_id
    returning id into v_variant_id;

    insert into public.supplier_skus (
      supplier_id, variant_id, supplier_sku, cost_usd, is_active, last_synced_at, last_cost_usd
    ) values (
      v_supplier.id, v_variant_id, (v_item ->> 'product_code'),
      round((v_item ->> 'price_usd')::numeric, 2), true, now(),
      round((v_item ->> 'price_usd')::numeric, 2)
    )
    on conflict (supplier_id, variant_id, supplier_sku) do update
      set cost_usd       = excluded.cost_usd,
          last_cost_usd  = excluded.last_cost_usd,
          last_synced_at = now(),
          is_active      = true;

    v_upserted := v_upserted + 1;
  end loop;

  return jsonb_build_object(
    'product_id', v_product_id,
    'slug', v_slug,
    'variants_synced', v_upserted
  );
end;
$$;

revoke execute on function public.supplier_upsert_catalogue(text, text, text, text, text, jsonb, jsonb)
  from public, anon, authenticated;


-- ============================================================================
-- 20261015000800_order_events_support.sql
-- ============================================================================

do $$ begin raise notice '>>> 20261015000800_order_events_support.sql'; end $$;

-- ============================================================================
-- Closes the schema gaps the specification names and the build did not have:
--
--   1. `order_events`  - an append-only status history. Every transition is
--      already made by a security definer RPC, so a trigger on `orders`
--      records them and no call site can forget to. Without it an order's
--      past is only inferable from timestamps.
--   2. `refund_pending` - the missing state. `failed -> refunded` used to be
--      the only path, which recorded a refund that a human had not yet made.
--      Money that has left the buyer's account needs a state that says
--      "agreed, not yet returned".
--   3. `support_tickets` - the "Contact support" action had nowhere to write.
--
-- Append-only is enforced by omission: no insert/update/delete grant reaches
-- `authenticated`, and the only writer is the trigger, which runs as definer.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. The missing order state
--
-- `add value if not exists` is idempotent, and the literal is only ever used
-- inside plpgsql bodies below, never in a top-level statement of this file, so
-- it is safe under a single-transaction apply (the SQL editor, `db push`).
-- ---------------------------------------------------------------------------
alter type public.order_status add value if not exists 'refund_pending';

-- Refund bookkeeping on the order itself.
alter table public.orders
  add column if not exists refund_reason text,
  add column if not exists refunded_at   timestamptz;

alter table public.payments
  add column if not exists refunded_at timestamptz;

-- ---------------------------------------------------------------------------
-- 2. order_events - append-only status history
-- ---------------------------------------------------------------------------
create table if not exists public.order_events (
  id          bigint generated always as identity primary key,
  order_id    uuid not null references public.orders (id) on delete cascade,
  -- Null on the 'created' row, which has no previous state.
  from_status public.order_status,
  to_status   public.order_status not null,
  -- Machine key for the UI: 'created', 'paid', 'delivering', 'delivered',
  -- 'failed', 'expired', 'refund_pending', 'refunded'.
  event       text not null,
  actor       text not null default 'system'
              check (actor in ('system', 'customer', 'staff', 'supplier')),
  actor_id    uuid,
  detail      jsonb,
  created_at  timestamptz not null default now()
);

create index if not exists order_events_order_idx
  on public.order_events (order_id, created_at desc, id desc);

-- The only writer. A security definer trigger rather than calls inside each
-- RPC: `expire_stale_orders` and `supplier_complete_item` both move status,
-- and a call the next author forgets is a hole in the history.
create or replace function private.log_order_status()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid   uuid := (select auth.uid());
  v_actor text := 'system';
begin
  -- deliver_order rewrites status to the same value on its second pass; the
  -- history should show the transition, not the no-op.
  if tg_op = 'UPDATE' and new.status is not distinct from old.status then
    return null;
  end if;

  if v_uid is not null then
    v_actor := case when public.is_staff() then 'staff' else 'customer' end;
  end if;

  insert into public.order_events (order_id, from_status, to_status, event, actor, actor_id)
  values (
    new.id,
    case when tg_op = 'UPDATE' then old.status else null end,
    new.status,
    case when tg_op = 'INSERT' then 'created' else new.status::text end,
    v_actor,
    v_uid
  );

  return null;
end;
$$;

drop trigger if exists orders_log_status on public.orders;
create trigger orders_log_status
  after insert or update of status on public.orders
  for each row execute function private.log_order_status();

-- ---------------------------------------------------------------------------
-- 3. support_tickets
-- ---------------------------------------------------------------------------
create table if not exists public.support_tickets (
  id          bigint generated always as identity primary key,
  user_id     uuid references public.profiles (id) on delete set null,
  order_id    uuid references public.orders (id) on delete set null,
  -- Kept separately: a buyer may want an answer at an address that is not the
  -- one they signed in with.
  contact     text,
  subject     text not null,
  body        text,
  status      text not null default 'open'
              check (status in ('open', 'in_progress', 'resolved', 'closed')),
  priority    text not null default 'normal'
              check (priority in ('low', 'normal', 'high')),
  admin_note  text,
  assigned_to uuid references public.profiles (id) on delete set null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  resolved_at timestamptz
);

create index if not exists support_tickets_user_idx
  on public.support_tickets (user_id, created_at desc);
create index if not exists support_tickets_open_idx
  on public.support_tickets (status, created_at desc)
  where status in ('open', 'in_progress');

drop trigger if exists support_tickets_touch on public.support_tickets;
create trigger support_tickets_touch before update on public.support_tickets
  for each row execute function private.touch_updated_at();

-- ---------------------------------------------------------------------------
-- 4. RLS + grants
--
-- Supabase sets default privileges that expose new public tables, so the
-- revoke is load-bearing, not decoration. RLS is not inherited either.
-- ---------------------------------------------------------------------------
alter table public.order_events    enable row level security;
alter table public.support_tickets enable row level security;

revoke all on public.order_events, public.support_tickets from anon, authenticated;

grant select on public.order_events to authenticated;
grant select on public.support_tickets to authenticated;

-- No insert/update/delete policy and no grant: writes only through RPC.
drop policy if exists order_events_select_own on public.order_events;
create policy order_events_select_own on public.order_events
  for select to authenticated
  using (
    public.is_staff()
    or exists (
      select 1 from public.orders o
      where o.id = order_events.order_id and o.user_id = (select auth.uid())
    )
  );

drop policy if exists support_tickets_select_own on public.support_tickets;
create policy support_tickets_select_own on public.support_tickets
  for select to authenticated
  using (user_id = (select auth.uid()) or public.is_staff());

drop policy if exists support_tickets_staff_all on public.support_tickets;
create policy support_tickets_staff_all on public.support_tickets
  for all to authenticated using (public.is_staff()) with check (public.is_staff());

-- ---------------------------------------------------------------------------
-- 5. Support RPCs
-- ---------------------------------------------------------------------------
create or replace function public.create_support_ticket(
  p_subject  text,
  p_body     text default null,
  p_order_id uuid default null,
  p_contact  text default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
  v_open integer;
  v_id   bigint;
begin
  if v_user is null then
    raise exception 'auth_required';
  end if;

  if coalesce(btrim(p_subject), '') = '' then
    raise exception 'subject_required';
  end if;

  -- The order may only be attached if it is the caller's own. A guessed UUID
  -- must not turn into a way to read someone else's order through the ticket.
  if p_order_id is not null and not exists (
    select 1 from public.orders o
    where o.id = p_order_id and o.user_id = v_user
  ) then
    raise exception 'order_not_found';
  end if;

  -- Abuse control: one ticket per 30 seconds, five open at a time.
  select count(*) into v_open
    from public.support_tickets
   where user_id = v_user and status in ('open', 'in_progress');

  if v_open >= 5 then
    raise exception 'too_many_open_tickets';
  end if;

  if exists (
    select 1 from public.support_tickets
    where user_id = v_user and created_at > now() - interval '30 seconds'
  ) then
    raise exception 'ticket_rate_limited';
  end if;

  insert into public.support_tickets (user_id, order_id, contact, subject, body)
  values (
    v_user,
    p_order_id,
    left(coalesce(p_contact, (select email from auth.users where id = v_user)), 200),
    left(btrim(p_subject), 200),
    left(p_body, 4000)
  )
  returning id into v_id;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_user, 'support_ticket_created', 'support_ticket', v_id::text,
          jsonb_build_object('order_id', p_order_id));

  return jsonb_build_object('ok', true, 'ticket_id', v_id);
end;
$$;

grant execute on function public.create_support_ticket(text, text, uuid, text) to authenticated;

create or replace function public.admin_support_set_status(
  p_ticket_id bigint,
  p_status    text,
  p_note      text default null,
  p_priority  text default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not public.is_staff() then
    raise exception 'not_authorized';
  end if;

  update public.support_tickets
     set status      = coalesce(p_status, status),
         priority    = coalesce(p_priority, priority),
         admin_note  = coalesce(p_note, admin_note),
         assigned_to = (select auth.uid()),
         resolved_at = case when p_status in ('resolved', 'closed') then now() else null end
   where id = p_ticket_id;

  if not found then
    raise exception 'ticket_not_found';
  end if;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values ((select auth.uid()), 'support_ticket_status', 'support_ticket', p_ticket_id::text,
          jsonb_build_object('status', p_status));
end;
$$;

grant execute on function public.admin_support_set_status(bigint, text, text, text) to authenticated;

-- ---------------------------------------------------------------------------
-- 6. Refund RPCs
--
-- The two halves are deliberately separate. `refund_pending` says a refund was
-- agreed; `refunded` says the money actually went back. Collapsing them is how
-- a store reports a refund it never made.
--
-- Neither function moves money. Automatic refunds of a failed supplier line
-- already credit the buyer's wallet in `supplier_complete_item`; these record a
-- refund made outside that path (an ABA reversal), so crediting again here
-- would pay the buyer twice.
-- ---------------------------------------------------------------------------
create or replace function public.admin_order_set_refund_pending(
  p_order_id uuid,
  p_reason   text default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare v_order public.orders;
begin
  if not public.is_staff() then
    raise exception 'not_authorized';
  end if;

  select * into v_order from public.orders where id = p_order_id for update;
  if not found then
    raise exception 'order_not_found';
  end if;

  -- 'pending' has captured no money to return, and the last two are terminal.
  if v_order.status not in ('paid', 'delivering', 'delivered', 'failed') then
    return jsonb_build_object('ok', false, 'status', v_order.status);
  end if;

  update public.orders
     set status = 'refund_pending',
         refund_reason = coalesce(p_reason, refund_reason)
   where id = p_order_id;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values ((select auth.uid()), 'order_refund_pending', 'order', p_order_id::text,
          jsonb_build_object('reason', p_reason, 'previous_status', v_order.status));

  return jsonb_build_object('ok', true, 'status', 'refund_pending');
end;
$$;

grant execute on function public.admin_order_set_refund_pending(uuid, text) to authenticated;

create or replace function public.admin_order_mark_refunded(
  p_order_id  uuid,
  p_reference text default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare v_order public.orders;
begin
  if not public.is_staff() then
    raise exception 'not_authorized';
  end if;

  select * into v_order from public.orders where id = p_order_id for update;
  if not found then
    raise exception 'order_not_found';
  end if;

  -- Only from refund_pending: marking a live order refunded would abandon a
  -- delivery that may still be running.
  if v_order.status <> 'refund_pending' then
    return jsonb_build_object('ok', false, 'status', v_order.status);
  end if;

  update public.payments
     set status = 'refunded', refunded_at = now()
   where order_id = p_order_id and status = 'succeeded';

  update public.orders
     set status = 'refunded', refunded_at = now()
   where id = p_order_id;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values ((select auth.uid()), 'order_refunded', 'order', p_order_id::text,
          jsonb_build_object('reference', p_reference));

  return jsonb_build_object('ok', true, 'status', 'refunded');
end;
$$;

grant execute on function public.admin_order_mark_refunded(uuid, text) to authenticated;


-- ============================================================================
-- 20261015000900_field_validation.sql
-- ============================================================================

do $$ begin raise notice '>>> 20261015000900_field_validation.sql'; end $$;

-- ============================================================================
-- Buyer field patterns were enforced in the app only.
--
-- `create_order` checked that a required field was non-empty and nothing else,
-- while `product_page.dart` and `checkout_page.dart` each applied the
-- catalogue's own `pattern`. The app is a suggestion: the RPC is directly
-- reachable, and an older build of the app is a normal thing to be running.
--
-- What that cost: `userid = 'abc'` was accepted, the buyer paid, the supplier
-- rejected the id, and the automatic path refunded the wallet. The sale was
-- never going to happen, and the store paid a support ticket and a refund for
-- finding that out. Field definitions live on `products.requires_fields`:
--
--   [{"key":"userid","label_en":"Game ID","placeholder":"123456789",
--     "pattern":"^[0-9]{6,12}$"}]
--
-- So enforce the pattern where the order is created, alongside the check that
-- already lives there. Two rules, both narrow:
--   * the value must match the field's own `pattern`, when it has one;
--   * the value must be at most 64 characters, which no real id or server name
--     needs and which stops a megabyte of junk reaching a supplier's API.
--
-- The app keeps its copy of the check so the buyer is told before paying. This
-- is the one that counts.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- field_pattern_matches: match a value against a catalogue pattern, and treat
-- an unusable pattern as "no constraint".
--
-- A pattern is data, entered by staff or written by an adapter, so it can be
-- wrong. If it is, `~` raises and every order for that product fails — a whole
-- game becomes unsellable over a typo in a validation string. Failing open
-- here is the lesser evil, and it matches what the client does with an
-- uncompilable pattern. The catalogue's own sanitising happens on write.
-- ---------------------------------------------------------------------------
create or replace function public.field_pattern_matches(
  p_value   text,
  p_pattern text
)
returns boolean
language plpgsql
immutable
set search_path = ''
as $$
begin
  if p_value is null or coalesce(p_pattern, '') = '' then
    return true;
  end if;

  return p_value ~ p_pattern;
exception
  when others then
    return true;
end;
$$;

comment on function public.field_pattern_matches(text, text) is
  'Buyer field pattern test. An invalid pattern is treated as no pattern, so a '
  'bad validation string cannot make a product unsellable.';

revoke execute on function public.field_pattern_matches(text, text)
  from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- create_order: same function, with the pattern and length rules added to the
-- existing non-empty check.
--
-- Re-created rather than amended, because the check lives inside it. The body
-- below is `20261015000300_rpc.sql` verbatim apart from the field gate and the
-- one extra local it needs.
-- ---------------------------------------------------------------------------
create or replace function public.create_order(
  p_items   jsonb,
  p_coupon  text default null,
  p_fields  jsonb default '{}'::jsonb,
  p_email   text default null,
  p_note    text default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user       uuid := (select auth.uid());
  v_profile    public.profiles;
  v_item       jsonb;
  v_variant    public.product_variants;
  v_product    public.products;
  v_qty        integer;
  v_stock      integer;
  v_subtotal   numeric(12, 2) := 0;
  v_discount   numeric(12, 2) := 0;
  v_total      numeric(12, 2);
  v_order_id   uuid;
  v_order_no   text;
  v_ttl        integer;
  v_required   jsonb;
  v_missing    text;
  v_invalid    text;
  v_has_stock  boolean := false;
begin
  if v_user is null then
    raise exception 'auth_required';
  end if;

  select * into v_profile from public.profiles where id = v_user;
  if v_profile.is_blocked then
    raise exception 'account_blocked';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'empty_cart';
  end if;

  if jsonb_array_length(p_items) > 20 then
    raise exception 'too_many_lines';
  end if;

  select order_ttl_minutes into v_ttl from public.settings where id;

  v_order_no := private.new_order_no();

  insert into public.orders (
    order_no, user_id, status, contact_email, customer_note, customer_fields, coupon_code, expires_at
  ) values (
    v_order_no, v_user, 'pending', p_email, p_note, coalesce(p_fields, '{}'::jsonb),
    nullif(btrim(coalesce(p_coupon, '')), ''),
    now() + make_interval(mins => v_ttl)
  ) returning id into v_order_id;

  for v_item in select * from jsonb_array_elements(p_items)
  loop
    v_qty := greatest(coalesce((v_item ->> 'qty')::integer, 1), 1);

    select * into v_variant
      from public.product_variants
     where id = (v_item ->> 'variant_id')::bigint
       and is_active;

    if not found then
      raise exception 'variant_unavailable' using detail = (v_item ->> 'variant_id');
    end if;

    select * into v_product from public.products where id = v_variant.product_id and is_active;
    if not found then
      raise exception 'product_unavailable';
    end if;

    if v_qty < v_variant.min_qty or v_qty > v_variant.max_qty then
      raise exception 'qty_out_of_range' using detail = v_variant.sku;
    end if;

    -- Per-product buyer fields (game id, server, ...)
    if v_product.requires_fields is not null and jsonb_array_length(v_product.requires_fields) > 0 then
      select string_agg(f ->> 'key', ', ')
        into v_missing
        from jsonb_array_elements(v_product.requires_fields) f
       where coalesce(btrim(p_fields ->> (f ->> 'key')), '') = '';

      if v_missing is not null then
        raise exception 'missing_fields' using detail = v_missing;
      end if;

      -- Bounded, and in the shape the catalogue declares. Without this the
      -- supplier is the first thing to reject a bad id, which it does after
      -- the buyer has paid.
      select string_agg(f ->> 'key', ', ')
        into v_invalid
        from jsonb_array_elements(v_product.requires_fields) f
       where length(btrim(p_fields ->> (f ->> 'key'))) > 64
          or not public.field_pattern_matches(
               btrim(p_fields ->> (f ->> 'key')),
               f ->> 'pattern'
             );

      if v_invalid is not null then
        raise exception 'invalid_fields' using detail = v_invalid;
      end if;
    end if;

    if v_variant.stock_mode = 'stock' then
      select count(*) into v_stock
        from private.stock_items s
       where s.variant_id = v_variant.id and s.status = 'available';

      if v_stock < v_qty then
        raise exception 'out_of_stock' using detail = v_variant.sku;
      end if;
      v_has_stock := true;
    end if;

    v_subtotal := v_subtotal + (v_variant.price_usd * v_qty);

    insert into public.order_items (
      order_id, variant_id, product_name, variant_label,
      unit_price_usd, qty, line_total_usd, unit_cost_usd
    ) values (
      v_order_id, v_variant.id, v_product.name_km, v_variant.label_km,
      v_variant.price_usd, v_qty, v_variant.price_usd * v_qty, v_variant.cost_usd
    );
  end loop;

  v_discount := private.coupon_discount(p_coupon, v_user, v_subtotal);
  v_total := greatest(v_subtotal - v_discount, 0);

  update public.orders
     set subtotal_usd = v_subtotal,
         discount_usd = v_discount,
         total_usd    = v_total
   where id = v_order_id;

  return jsonb_build_object(
    'order_id', v_order_id,
    'order_no', v_order_no,
    'subtotal_usd', v_subtotal,
    'discount_usd', v_discount,
    'total_usd', v_total,
    'expires_in_minutes', v_ttl
  );
end;
$$;


-- ============================================================================
-- 20261015001000_manual_payment.sql
-- ============================================================================

do $$ begin raise notice '>>> 20261015001000_manual_payment.sql'; end $$;

-- ============================================================================
-- Manual KHQR fallback: a transfer a human confirms.
--
-- The automated path is PayWay: `payway-init` returns a per-order KHQR,
-- `payway-verify` polls, and the settlement lands in `mark_order_paid`. That is
-- the path to prefer, and this does not replace it. What it covers is the case
-- where it cannot run at all — no PayWay credential on the project, or a buyer
-- whose bank app will not open the deeplink — and the alternative today is that
-- the order cannot be paid for.
--
-- Three rules, and the shape of all three is deliberate:
--
--   1. There is still ONE settlement path. `mark_order_paid` is called with
--      provider 'manual' (the enum value already existed, unused). Stock
--      allocation, coupon redemption, the wallet top-up branch and the supplier
--      queue therefore behave exactly as they do after a PayWay settlement.
--      A second implementation is how the two drift apart and money moves twice.
--
--   2. The amount is stated, not assumed. PayWay has no choice but to ask ABA
--      what was paid (`_shared/settle.ts` compares that against the order total
--      and refuses to deliver on a shortfall). A human has to do the same: the
--      staff member enters what landed, and the RPC refuses anything below the
--      total. "The buyer said they paid" is not an amount.
--
--   3. A screenshot is never evidence and a transfer reference is never reused.
--      `payments` is unique on (provider, provider_ref). Confirming a second
--      order with a reference already on a first one would silently re-point the
--      existing row while still settling the second order — one transfer paid
--      for two orders. The RPC refuses that outright.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. Order state, and how long a buyer gets after asking to pay by transfer
-- ---------------------------------------------------------------------------
alter table public.orders
  add column if not exists manual_payment_requested_at timestamptz,
  add column if not exists manual_payment_note         text;

comment on column public.orders.manual_payment_requested_at is
  'Set when the buyer asks to pay by transfer instead of KHQR. Cleared when '
  'staff confirm or dismiss it.';

alter table public.settings
  add column if not exists manual_grace_minutes integer not null default 1440;

comment on column public.settings.manual_grace_minutes is
  'How long an order stays payable after the buyer asks to pay by transfer. '
  'An instant transfer is not instant: the default 15-minute TTL expires the '
  'order before the money arrives, and staff would then be confirming an order '
  'that housekeeping has already cancelled.';

-- The app reads the view, not the table.
create or replace view public.public_settings as
select
  id, site_name, support_telegram, support_email, usd_to_khr, order_ttl_minutes,
  khqr_account_id, khqr_merchant_name, khqr_merchant_city, is_maintenance,
  topup_min_usd, topup_max_usd, telegram_bot_username, manual_grace_minutes
from public.settings;

grant select on public.public_settings to anon, authenticated;

-- ---------------------------------------------------------------------------
-- 2. The buyer asks
--
-- No money moves here. This books a request and keeps the order payable long
-- enough for the transfer to land.
-- ---------------------------------------------------------------------------
create or replace function public.request_manual_payment(
  p_order_id uuid,
  p_note     text default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user   uuid := (select auth.uid());
  v_order  public.orders;
  v_grace  integer;
  v_recent integer;
begin
  if v_user is null then
    raise exception 'auth_required';
  end if;

  select * into v_order
    from public.orders
   where id = p_order_id and user_id = v_user
   for update;

  -- Own order only, and the same error either way so a guessed UUID cannot be
  -- used to find out whether an order exists.
  if not found then
    raise exception 'order_not_found';
  end if;

  if v_order.status <> 'pending' then
    raise exception 'order_not_pending' using detail = v_order.status::text;
  end if;

  -- Asking twice keeps the first request: a repeat must not push the expiry out
  -- again, or the flag becomes a way to hold a price indefinitely.
  if v_order.manual_payment_requested_at is not null then
    return jsonb_build_object(
      'ok', true,
      'already_requested', true,
      'requested_at', v_order.manual_payment_requested_at,
      'expires_at', v_order.expires_at
    );
  end if;

  -- Abuse control: three requests an hour, counting the ones already made.
  select count(*) into v_recent
    from public.orders
   where user_id = v_user
     and manual_payment_requested_at > now() - interval '1 hour';

  if v_recent >= 3 then
    raise exception 'manual_rate_limited';
  end if;

  select coalesce(nullif(manual_grace_minutes, 0), 1440)
    into v_grace
    from public.settings where id;

  update public.orders
     set manual_payment_requested_at = now(),
         manual_payment_note = left(nullif(btrim(coalesce(p_note, '')), ''), 300),
         -- Never shortens an order that already had longer to run.
         expires_at = greatest(expires_at, now() + make_interval(mins => v_grace))
   where id = p_order_id
  returning * into v_order;

  -- No status change, so the trigger stays quiet and this is written here. The
  -- history is meant to show that the buyer asked, not only what the status did.
  insert into public.order_events (
    order_id, from_status, to_status, event, actor, actor_id, detail
  ) values (
    p_order_id, 'pending', 'pending', 'manual_payment_requested', 'customer', v_user,
    jsonb_strip_nulls(jsonb_build_object(
      'note', v_order.manual_payment_note,
      'expires_at', v_order.expires_at,
      'grace_minutes', v_grace
    ))
  );

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (v_user, 'manual_payment_requested', 'order', p_order_id::text,
          jsonb_build_object('order_no', v_order.order_no, 'grace_minutes', v_grace));

  return jsonb_build_object(
    'ok', true,
    'already_requested', false,
    'requested_at', v_order.manual_payment_requested_at,
    'expires_at', v_order.expires_at
  );
end;
$$;

grant execute on function public.request_manual_payment(uuid, text) to authenticated;

-- ---------------------------------------------------------------------------
-- 3. Staff confirm what actually arrived
--
-- Staff-only, and it delegates the settlement itself: the same
-- `mark_order_paid` the PayWay path calls, so nothing new moves money.
-- ---------------------------------------------------------------------------
create or replace function public.admin_confirm_manual_payment(
  p_order_id   uuid,
  p_amount_usd numeric,
  p_aba_ref    text,
  p_note       text default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_order     public.orders;
  v_ref       text := btrim(coalesce(p_aba_ref, ''));
  v_other     text;
  v_result    jsonb;
begin
  if not public.is_staff() then
    raise exception 'not_authorized';
  end if;

  if p_amount_usd is null or p_amount_usd <= 0 then
    raise exception 'amount_required';
  end if;

  -- The reference is the only thing standing between one transfer and two
  -- orders, so it is required rather than optional.
  if v_ref = '' then
    raise exception 'manual_reference_required';
  end if;

  select * into v_order from public.orders where id = p_order_id for update;
  if not found then
    raise exception 'order_not_found';
  end if;

  -- Already settled: report it rather than raising, so the screen can say so
  -- instead of showing an error for a double click.
  if v_order.status <> 'pending' then
    return jsonb_build_object('ok', false, 'status', v_order.status);
  end if;

  -- An expired order is not settled here. The money is real, so it goes down the
  -- external-refund path (admin_order_set_refund_pending -> admin_order_mark_refunded)
  -- where a human handles it, rather than being quietly accepted into an order
  -- that housekeeping has already cancelled.
  if v_order.expires_at <= now() then
    raise exception 'order_expired';
  end if;

  -- What landed must cover the total. Same rule the automated path applies.
  if p_amount_usd + 0.0001 < v_order.total_usd then
    raise exception 'manual_underpaid' using detail = v_order.total_usd::text;
  end if;

  -- One transfer, one order.
  select o.order_no into v_other
    from public.payments p
    join public.orders o on o.id = p.order_id
   where p.provider = 'manual'
     and p.provider_ref = v_ref
     and p.order_id <> p_order_id
   limit 1;

  if v_other is not null then
    raise exception 'manual_reference_used' using detail = v_other;
  end if;

  -- Written before the settlement so the history reads in the order things
  -- happened. Both statements are in this transaction, so a failure in the
  -- settlement takes the entry with it.
  insert into public.order_events (
    order_id, from_status, to_status, event, actor, actor_id, detail
  ) values (
    p_order_id, 'pending', 'paid', 'manual_payment_confirmed', 'staff',
    (select auth.uid()),
    jsonb_build_object(
      'aba_ref', v_ref,
      'declared_amount_usd', p_amount_usd,
      'total_usd', v_order.total_usd
    )
  );

  v_result := public.mark_order_paid(
    p_order_id,
    'manual',
    v_ref,
    null,
    jsonb_strip_nulls(jsonb_build_object(
      'verified_by', (select auth.uid()),
      'declared_amount_usd', p_amount_usd,
      'note', nullif(btrim(coalesce(p_note, '')), '')
    )),
    null
  );

  -- Settled, so it leaves the queue. The request itself stays in the order
  -- history, where it belongs.
  update public.orders
     set manual_payment_requested_at = null,
         manual_payment_note = null
   where id = p_order_id;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values ((select auth.uid()), 'manual_payment_confirmed', 'order', p_order_id::text,
          jsonb_build_object(
            'order_no', v_order.order_no,
            'aba_ref', v_ref,
            'declared_amount_usd', p_amount_usd
          ));

  return v_result || jsonb_build_object('provider', 'manual', 'aba_ref', v_ref);
end;
$$;

grant execute on function public.admin_confirm_manual_payment(uuid, numeric, text, text)
  to authenticated;

-- ---------------------------------------------------------------------------
-- 4. Staff dismiss a request that will not be paid
--
-- Without this the queue only grows. No money moves and nothing is refunded:
-- the order simply goes back to being an unpaid order that can expire.
-- ---------------------------------------------------------------------------
create or replace function public.admin_clear_manual_payment_request(
  p_order_id uuid,
  p_reason   text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_order public.orders;
begin
  if not public.is_staff() then
    raise exception 'not_authorized';
  end if;

  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'reason_required';
  end if;

  select * into v_order from public.orders where id = p_order_id for update;
  if not found then
    raise exception 'order_not_found';
  end if;

  update public.orders
     set manual_payment_requested_at = null,
         manual_payment_note = null
   where id = p_order_id;

  insert into public.order_events (
    order_id, from_status, to_status, event, actor, actor_id, detail
  ) values (
    p_order_id, v_order.status, v_order.status, 'manual_payment_cleared', 'staff',
    (select auth.uid()), jsonb_build_object('reason', left(btrim(p_reason), 300))
  );

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values ((select auth.uid()), 'manual_payment_cleared', 'order', p_order_id::text,
          jsonb_build_object('order_no', v_order.order_no, 'reason', left(btrim(p_reason), 300)));

  return jsonb_build_object('ok', true, 'status', v_order.status);
end;
$$;

grant execute on function public.admin_clear_manual_payment_request(uuid, text)
  to authenticated;

-- ---------------------------------------------------------------------------
-- 5. The staff queue, as a view
--
-- `security_invoker` is not decoration. A plain view belongs to its owner and
-- reads the base table as that owner, which would hand every customer in the
-- table to any signed-in caller. With security_invoker the policies on `orders`
-- apply to whoever queries it, so a staff session gets the queue and a customer
-- session gets nothing.
-- ---------------------------------------------------------------------------
create or replace view public.staff_manual_payments
with (security_invoker = true) as
select
  o.id            as order_id,
  o.order_no,
  o.status,
  o.total_usd,
  o.kind,
  o.manual_payment_requested_at as requested_at,
  o.manual_payment_note         as buyer_note,
  o.expires_at,
  o.created_at,
  o.customer_fields,
  o.contact_email
from public.orders o
where o.manual_payment_requested_at is not null
  and o.status = 'pending'
order by o.manual_payment_requested_at;

comment on view public.staff_manual_payments is
  'Orders where the buyer has asked to pay by transfer. Empty the queue with '
  'admin_confirm_manual_payment or admin_clear_manual_payment_request.';

grant select on public.staff_manual_payments to authenticated;


-- ============================================================================
-- 20261015001100_admin_overview.sql
-- ============================================================================

do $$ begin raise notice '>>> 20261015001100_admin_overview.sql'; end $$;

-- ============================================================================
-- The staff overview, as numbers that can be checked against a bank statement.
--
-- Everything a dashboard is tempted to invent — growth, "active users", a
-- conversion rate — is left out. What is here comes from two places only:
--
--   * `orders` counts, by status. A row is a row.
--   * `payments` sums, split by where the money came from.
--
-- The split matters. A wallet-funded purchase creates a `payments` row with
-- provider 'wallet' and no money arrives; the cash arrived earlier, when the
-- balance was topped up. Summing `orders.total_usd` therefore counts one
-- barrel of money twice, once as the top-up and again as the purchase it paid
-- for. So:
--
--   received_*   money that reached the bank (payway / khqr_direct / manual)
--   wallet_spent_* orders settled from a balance — not new money
--   refunded_*   reported separately and never netted off
--
-- A refunded payment still counts as received: it did arrive. Netting it out of
-- the window it arrived in would silently rewrite history, and the pair of
-- figures reads as gross and returns, which is what a bookkeeper can reconcile.
--
-- One more thing that is easy to get wrong: `now()` is UTC and the store is in
-- Phnom Penh, so "today" is a seven-hours-elsewhere boundary. It is computed in
-- the store's timezone here, and the timezone is returned with the numbers so
-- the screen can say which day it means.
-- ============================================================================

create or replace function public.admin_overview()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tz        text := 'Asia/Phnom_Penh';
  v_day_start timestamptz;
  v_7d        timestamptz;
  v_30d       timestamptz;
begin
  if not public.is_staff() then
    raise exception 'not_authorized';
  end if;

  v_day_start := date_trunc('day', now() at time zone v_tz) at time zone v_tz;
  v_7d        := now() - interval '7 days';
  v_30d       := now() - interval '30 days';

  return jsonb_build_object(
    'timezone', v_tz,
    'generated_at', now(),

    -- Work waiting for a person, each one a queue that exists elsewhere in the
    -- app. They are here so the overview answers "what needs doing".
    'orders_pending', (select count(*) from public.orders o
                        where o.status = 'pending'),
    'orders_refund_pending', (select count(*) from public.orders o
                               where o.status = 'refund_pending'),
    'transfers_waiting', (select count(*) from public.orders o
                           where o.manual_payment_requested_at is not null
                             and o.status = 'pending'),
    'support_open', (select count(*) from public.support_tickets t
                      where t.status in ('open', 'in_progress')),
    'items_manual_waiting', (select count(*) from public.order_items i
                              where i.delivery_status = 'manual_waiting'),

    -- Money into the bank.
    'received_today', (select count(*) from public.payments p
                        where p.provider in ('payway', 'khqr_direct', 'manual')
                          and p.status in ('succeeded', 'refunded')
                          and p.verified_at >= v_day_start),
    'received_today_usd', (select coalesce(sum(p.amount_usd), 0) from public.payments p
                            where p.provider in ('payway', 'khqr_direct', 'manual')
                              and p.status in ('succeeded', 'refunded')
                              and p.verified_at >= v_day_start),
    'received_7d_usd', (select coalesce(sum(p.amount_usd), 0) from public.payments p
                         where p.provider in ('payway', 'khqr_direct', 'manual')
                           and p.status in ('succeeded', 'refunded')
                           and p.verified_at >= v_7d),
    'received_30d_usd', (select coalesce(sum(p.amount_usd), 0) from public.payments p
                          where p.provider in ('payway', 'khqr_direct', 'manual')
                            and p.status in ('succeeded', 'refunded')
                            and p.verified_at >= v_30d),

    -- Balance spent, which is not new money.
    'wallet_spent_30d_usd', (select coalesce(sum(p.amount_usd), 0) from public.payments p
                              where p.provider = 'wallet'
                                and p.status = 'succeeded'
                                and p.verified_at >= v_30d),

    -- Money paid back out.
    'refunds_30d', (select count(*) from public.orders o
                     where o.refunded_at >= v_30d),
    'refunded_30d_usd', (select coalesce(sum(o.total_usd), 0) from public.orders o
                          where o.refunded_at >= v_30d)
  );
end;
$$;

grant execute on function public.admin_overview() to authenticated;


-- ============================================================================
-- 20261015001200_support_note_fix.sql
-- ============================================================================

do $$ begin raise notice '>>> 20261015001200_support_note_fix.sql'; end $$;

-- ============================================================================
-- One bug in `admin_support_set_status`, found while building the staff Support
-- screen: `resolved_at` was written on every call, not only when the status
-- changed.
--
--     resolved_at = case when p_status in ('resolved','closed')
--                        then now() else null end
--
-- The parameters are `coalesce`d on purpose so a caller can update one field —
-- the signature documents `p_status` as optional. But with `p_status = null`
-- that expression evaluates to null, so saving a note on a resolved ticket
-- silently wiped the time it was resolved. The history then says the ticket was
-- resolved and does not say when, which is the one thing resolved_at is for.
--
-- The re-created function only touches `resolved_at` when a status is actually
-- being set. A note-only call leaves the resolution time alone.
-- ============================================================================

create or replace function public.admin_support_set_status(
  p_ticket_id bigint,
  p_status    text,
  p_note      text default null,
  p_priority  text default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not public.is_staff() then
    raise exception 'not_authorized';
  end if;

  update public.support_tickets
     set status      = coalesce(p_status, status),
         priority    = coalesce(p_priority, priority),
         admin_note  = coalesce(p_note, admin_note),
         assigned_to = (select auth.uid()),
         -- Null status means "not talking about the status": keep whatever
         -- resolution time is already recorded.
         resolved_at = case
                         when p_status in ('resolved', 'closed') then now()
                         when p_status is null then resolved_at
                         else null
                       end
   where id = p_ticket_id;

  if not found then
    raise exception 'ticket_not_found';
  end if;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values ((select auth.uid()), 'support_ticket_status', 'support_ticket', p_ticket_id::text,
          jsonb_build_object('status', p_status, 'priority', p_priority));
end;
$$;

grant execute on function public.admin_support_set_status(bigint, text, text, text) to authenticated;


-- ============================================================================
-- 20261015001300_supplier_price_follows_cost.sql
-- ============================================================================

do $$ begin raise notice '>>> 20261015001300_supplier_price_follows_cost.sql'; end $$;

-- ============================================================================
-- A synced SKU that nobody has repriced kept its first sync's price forever.
--
-- `supplier_upsert_catalogue` updated `cost_usd` on a re-sync but never
-- `price_usd`. That is right for a retail price staff set by hand, which must
-- survive a sync. It is wrong for an unpriced SKU: its price IS its cost, so
-- when the supplier moved the cost, the storefront kept selling at the old one.
--
-- Fix: on re-sync, move `price_usd` to the new cost only while it still equals
-- the previous cost. Anything staff changed is left alone.
--
-- Only the variant upsert changes. The function is re-created in full because
-- plpgsql bodies cannot be patched. The grant from 700 survives `create or
-- replace`.
-- ============================================================================

create or replace function public.supplier_upsert_catalogue(
  p_supplier_code text,
  p_game_code     text,
  p_name          text,
  p_image_url     text,
  p_summary       text,
  p_required_fields jsonb,      -- ["userid","serverid"] or [{ key, label_km, label_en }]
  p_products      jsonb         -- [{ product_code, name, price_usd }]
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_supplier public.suppliers;
  v_product_id bigint;
  v_slug text;
  v_item jsonb;
  v_variant_id bigint;
  v_fields jsonb;
  v_upserted integer := 0;
begin
  select * into v_supplier from public.suppliers where code = p_supplier_code;
  if not found then
    raise exception 'unknown_supplier' using detail = p_supplier_code;
  end if;

  v_slug := p_supplier_code || '-' || p_game_code;
  v_fields := public.supplier_field_definitions(p_required_fields);

  insert into public.products (
    slug, name_km, name_en, summary_km, summary_en, image_url, kind,
    requires_fields, supplier_id, supplier_game_code, is_active, sort_order
  ) values (
    v_slug, p_name, p_name, p_summary, p_summary, p_image_url, 'auto_topup',
    v_fields, v_supplier.id, p_game_code, true, 1000
  )
  on conflict (slug) do update
    set name_km       = excluded.name_km,
        name_en       = excluded.name_en,
        summary_km    = excluded.summary_km,
        summary_en    = excluded.summary_en,
        image_url     = coalesce(excluded.image_url, public.products.image_url),
        requires_fields = excluded.requires_fields,
        supplier_id   = excluded.supplier_id,
        supplier_game_code = excluded.supplier_game_code,
        updated_at    = now()
  returning id into v_product_id;

  for v_item in select * from jsonb_array_elements(p_products)
  loop
    if coalesce(btrim(v_item ->> 'product_code'), '') = '' then
      raise exception 'product_missing_code'
        using detail = left(v_item::text, 200);
    end if;

    insert into public.product_variants (
      product_id, sku, label_km, label_en, price_usd, cost_usd,
      stock_mode, min_qty, max_qty, is_active, sort_order
    ) values (
      v_product_id,
      (v_item ->> 'product_code'),
      (v_item ->> 'name'),
      (v_item ->> 'name'),
      -- The supplier price is cost. Retail is set by staff afterwards; until
      -- then it is cost, so an unpriced SKU can never be sold at a loss.
      round((v_item ->> 'price_usd')::numeric, 2),
      round((v_item ->> 'price_usd')::numeric, 2),
      'unlimited', 1, 50, true, coalesce((v_item ->> 'sort')::int, 0)
    )
    on conflict (sku) do update
      set label_km   = excluded.label_km,
          label_en   = excluded.label_en,
          -- Read the OLD cost before it is overwritten below: an unpriced SKU
          -- (price = old cost) follows the supplier; a staff price does not.
          price_usd  = case
                         when public.product_variants.price_usd = public.product_variants.cost_usd
                           then excluded.cost_usd
                         else public.product_variants.price_usd
                       end,
          cost_usd   = excluded.cost_usd,
          sort_order = excluded.sort_order,
          is_active  = true,
          product_id = excluded.product_id
    returning id into v_variant_id;

    insert into public.supplier_skus (
      supplier_id, variant_id, supplier_sku, cost_usd, is_active, last_synced_at, last_cost_usd
    ) values (
      v_supplier.id, v_variant_id, (v_item ->> 'product_code'),
      round((v_item ->> 'price_usd')::numeric, 2), true, now(),
      round((v_item ->> 'price_usd')::numeric, 2)
    )
    on conflict (supplier_id, variant_id, supplier_sku) do update
      set cost_usd       = excluded.cost_usd,
          last_cost_usd  = excluded.last_cost_usd,
          last_synced_at = now(),
          is_active      = true;

    v_upserted := v_upserted + 1;
  end loop;

  return jsonb_build_object(
    'product_id', v_product_id,
    'slug', v_slug,
    'variants_synced', v_upserted
  );
end;
$$;


-- ============================================================================
-- 20261015001400_referral_codes.sql
-- ============================================================================

do $$ begin raise notice '>>> 20261015001400_referral_codes.sql'; end $$;

-- ============================================================================
-- Referral attribution.
--
-- `profiles.referral_code` has been generated since the first migration, and
-- `profiles.referred_by` has existed just as long, but nothing ever wrote it:
-- the column was decorative. This adds the one server-side call that fills it,
-- so the signup form can accept a friend's code.
--
-- Every rule lives here, not in the app, because the app is not the authority:
--   * the code must belong to an existing, unblocked profile
--   * nobody refers themselves
--   * first code wins; a later call is a no-op, so a UI retry cannot
--     re-attribute an account to somebody else
--
-- No coins or wallet credit move here. Rewarding a referrer is a campaign
-- decision (rate, cap, when it pays) and belongs in its own migration once ops
-- pick one, rather than being invented at signup time.
-- ============================================================================

create or replace function public.apply_referral_code(p_code text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user  uuid := (select auth.uid());
  v_code  text := upper(trim(coalesce(p_code, '')));
  v_owner uuid;
begin
  if v_user is null then raise exception 'auth_required'; end if;
  if v_code = '' then raise exception 'referral_code_required'; end if;

  select p.id into v_owner
    from public.profiles p
   where p.referral_code = v_code
     and p.is_blocked is false;

  if v_owner is null then raise exception 'referral_code_unknown'; end if;
  if v_owner = v_user then raise exception 'referral_code_self'; end if;

  update public.profiles
     set referred_by = v_owner
   where id = v_user
     and referred_by is null;
end;
$$;

grant execute on function public.apply_referral_code(text) to authenticated;


-- ============================================================================
-- 20261015001500_admin_catalogue_queue.sql
-- ============================================================================

do $$ begin raise notice '>>> 20261015001500_admin_catalogue_queue.sql'; end $$;

-- ============================================================================
-- Staff controls for the catalogue and the supplier queue.
--
-- Products and variants have no write grants for `authenticated`, by design:
-- every write goes through a definer RPC that re-checks `is_staff()`. Until now
-- staff could only change a product with raw SQL.
--
--   admin_product_set_active   show or hide a product
--   admin_variant_set_price    set a retail price; refused below cost
--   admin_supplier_queue       lines the supplier worker could not finish
-- ============================================================================

create or replace function public.admin_product_set_active(
  p_product_id bigint,
  p_active     boolean
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare v_slug text;
begin
  if not public.is_staff() then raise exception 'not_authorized'; end if;
  if p_active is null then raise exception 'invalid_active'; end if;

  update public.products
     set is_active = p_active
   where id = p_product_id
  returning slug into v_slug;

  if not found then raise exception 'product_not_found'; end if;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values ((select auth.uid()), 'product_set_active', 'product', p_product_id::text,
          jsonb_build_object('slug', v_slug, 'is_active', p_active));

  return jsonb_build_object('ok', true, 'id', p_product_id, 'is_active', p_active);
end;
$$;

grant execute on function public.admin_product_set_active(bigint, boolean) to authenticated;

create or replace function public.admin_variant_set_price(
  p_variant_id bigint,
  p_price_usd  numeric
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_cost numeric;
  v_old  numeric;
begin
  if not public.is_staff() then raise exception 'not_authorized'; end if;
  if p_price_usd is null or p_price_usd <= 0 then raise exception 'invalid_price'; end if;

  select cost_usd, price_usd into v_cost, v_old
    from public.product_variants
   where id = p_variant_id
     for update;

  if not found then raise exception 'variant_not_found'; end if;

  -- A sale below what the supplier charges loses money on every order. Refuse
  -- it here, not only in the app.
  if v_cost is not null and round(p_price_usd, 2) < v_cost then
    raise exception 'price_below_cost' using detail = v_cost::text;
  end if;

  update public.product_variants
     set price_usd = round(p_price_usd, 2)
   where id = p_variant_id;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values ((select auth.uid()), 'variant_set_price', 'product_variant', p_variant_id::text,
          jsonb_build_object('old_price_usd', v_old, 'new_price_usd', round(p_price_usd, 2),
                             'cost_usd', v_cost));

  return jsonb_build_object('ok', true, 'id', p_variant_id,
                            'price_usd', round(p_price_usd, 2));
end;
$$;

grant execute on function public.admin_variant_set_price(bigint, numeric) to authenticated;

-- Two states, because they need different action. `retrying` is the worker
-- backing off (the line will try again on its own). `manual_waiting` has used
-- its attempts and needs a person.
create or replace function public.admin_supplier_queue(p_limit integer default 50)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not public.is_staff() then raise exception 'not_authorized'; end if;

  return coalesce((
    select jsonb_agg(row_to_json(q) order by q.state, q.item_id)
      from (
        select oi.id as item_id,
               o.id as order_id,
               o.order_no,
               oi.product_name,
               oi.variant_label,
               oi.qty,
               s.code as supplier_code,
               oi.delivery_status,
               case when oi.delivery_status = 'manual_waiting' then 'manual_waiting'
                    else 'retrying' end as state,
               oi.supplier_attempts,
               oi.supplier_last_error,
               oi.supplier_next_attempt_at,
               o.created_at
          from public.order_items oi
          join public.orders o on o.id = oi.order_id
          left join public.product_variants v on v.id = oi.variant_id
          left join public.products p on p.id = v.product_id
          left join public.suppliers s on s.id = p.supplier_id
         where oi.delivery_status in ('pending', 'manual_waiting')
           and (oi.delivery_status = 'manual_waiting' or oi.supplier_attempts > 0)
         order by oi.id
         limit least(greatest(coalesce(p_limit, 50), 1), 200)
      ) q
  ), '[]'::jsonb);
end;
$$;

grant execute on function public.admin_supplier_queue(integer) to authenticated;


-- ============================================================================
-- 20261016100000_admin_roles.sql
-- ============================================================================

do $$ begin raise notice '>>> 20261016100000_admin_roles.sql'; end $$;

-- ============================================================================
-- Role management.
--
-- Until now a role changed only by SQL. This adds the in-app path for admins
-- and one bootstrap call that the setup script runs once with the database
-- owner.
--
--   admin_set_role(user, role)  admins only; refuses a self-change, so the
--                               acting admin always stays one; audited
--   admin_find_user(email)      admins only; looks a sign-up up by email
--   admin_list_staff()          admins only; staff and admins
--   bootstrap_admin(email)      NOT granted to any app role. Run by the setup
--                               script as the database owner. Never reachable
--                               from the client, so "first signup wins" is
--                               impossible.
-- ============================================================================

create or replace function public.admin_set_role(
  p_user_id uuid,
  p_role    public.app_role
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_old  public.app_role;
  v_name text;
begin
  if not public.is_admin() then raise exception 'not_authorized'; end if;
  if p_role is null then raise exception 'invalid_role'; end if;
  if p_user_id = (select auth.uid()) then raise exception 'cannot_change_own_role'; end if;

  select role, display_name into v_old, v_name
    from public.profiles
   where id = p_user_id
     for update;

  if not found then raise exception 'user_not_found'; end if;

  update public.profiles set role = p_role where id = p_user_id;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values ((select auth.uid()), 'role_change', 'profile', p_user_id::text,
          jsonb_build_object('from', v_old, 'to', p_role, 'name', v_name));

  return jsonb_build_object('ok', true, 'id', p_user_id, 'role', p_role);
end;
$$;

grant execute on function public.admin_set_role(uuid, public.app_role) to authenticated;

create or replace function public.admin_find_user(p_email text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare v_row jsonb;
begin
  if not public.is_admin() then raise exception 'not_authorized'; end if;

  select jsonb_build_object('id', p.id, 'display_name', p.display_name, 'role', p.role)
    into v_row
    from auth.users u
    join public.profiles p on p.id = u.id
   where lower(u.email) = lower(btrim(coalesce(p_email, '')));

  if v_row is null then raise exception 'user_not_found'; end if;
  return v_row;
end;
$$;

grant execute on function public.admin_find_user(text) to authenticated;

create or replace function public.admin_list_staff()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not public.is_admin() then raise exception 'not_authorized'; end if;

  return coalesce((
    select jsonb_agg(jsonb_build_object('id', p.id, 'display_name', p.display_name, 'role', p.role)
                     order by case p.role when 'admin' then 0 else 1 end, p.display_name)
      from public.profiles p
     where p.role in ('staff', 'admin')
  ), '[]'::jsonb);
end;
$$;

grant execute on function public.admin_list_staff() to authenticated;

create or replace function public.bootstrap_admin(p_email text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare v_id uuid;
begin
  select u.id into v_id
    from auth.users u
   where lower(u.email) = lower(btrim(coalesce(p_email, '')));

  if v_id is null then raise exception 'user_not_found' using detail = 'sign up first, then run the bootstrap'; end if;

  update public.profiles set role = 'admin' where id = v_id;

  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (null, 'bootstrap_admin', 'profile', v_id::text, jsonb_build_object('email', p_email));

  return jsonb_build_object('ok', true, 'id', v_id, 'role', 'admin');
end;
$$;

revoke all on function public.bootstrap_admin(text) from public, anon, authenticated;


-- ============================================================================
-- 20261016110000_supplier_grants.sql
-- ============================================================================

do $$ begin raise notice '>>> 20261016110000_supplier_grants.sql'; end $$;

-- ============================================================================
-- Supplier tables were unreadable by the staff screens.
--
-- `0002_rls.sql` gave both tables `for all to authenticated using (is_staff())`
-- policies, but never a table privilege. A policy alone grants nothing: the
-- staff catalogue embeds `supplier:suppliers ( code )`, so PostgREST answered
--
--   403 {"code":"42501","hint":"Grant the required privileges to the current
--        role with: GRANT SELECT ON public.suppliers TO authenticated;"}
--
-- and `AdminCataloguePage` showed "something went wrong" with an empty list.
--
-- SELECT only. Nothing in the app writes either table; a supplier is added by
-- code, and the sync worker uses the service key. The `for all` policies stay
-- in place so the grant can be widened the day a screen needs to write.
-- Neither table holds a secret: `suppliers` is code/name/base_url/is_active and
-- `supplier_skus` is a mapping plus cost. Prices and keys live elsewhere.
-- ============================================================================

grant select on public.suppliers to authenticated;
grant select on public.supplier_skus to authenticated;


-- ============================================================================
-- 20261016120000_supplier_catalogue_fit.sql
-- ============================================================================

do $$ begin raise notice '>>> 20261016120000_supplier_catalogue_fit.sql'; end $$;

-- ============================================================================
-- Catalogue fit with the supplier: quantity, and SKUs the supplier dropped.
--
-- Two ways a synced catalogue could take money it cannot deliver on:
--
-- 1. QUANTITY. Sync wrote every variant as min_qty=1, max_qty=50. Bay2Game's
--    /create_order takes a product_code and buyer fields only — no quantity —
--    so a line for two would be delivered once. The adapter now declares
--    `supportsQuantity: false`, the sync passes `max_qty: 1`, and this function
--    stores it. create_order already validates qty against the variant's
--    min_qty/max_qty in Postgres, so the cap is enforced server-side even if a
--    client ignores it, and the quantity stepper disappears on its own.
--
-- 2. STALE SKUs. Sync only ever set is_active = true. A product the supplier
--    removed stayed sellable, so the buyer paid and the order could only be
--    refunded. A sync is now a snapshot: anything this supplier no longer
--    lists for the game is deactivated, and a game left with nothing on sale is
--    hidden instead of shown empty.
--
-- An empty product list is deliberately NOT a snapshot. A supplier having a bad
-- day, a rate limit answered with an empty body, or a game whose packages are
-- all inactive would otherwise empty the shop in one call. Nothing is
-- deactivated unless the pull actually returned products.
--
-- The body below carries forward the two behaviours earlier migrations added to
-- this same function — field normalisation (20261015000700) and an unpriced
-- SKU following the supplier's cost (20261015001300) — because plpgsql bodies
-- cannot be patched. Dropping either one silently breaks a tested guarantee;
-- `smoke.sql` checks both.
-- ============================================================================

create or replace function public.supplier_upsert_catalogue(
  p_supplier_code   text,
  p_game_code       text,
  p_name            text,
  p_image_url       text,
  p_summary         text,
  p_required_fields jsonb,      -- [{ key, label_km, label_en, placeholder }]
  p_products        jsonb       -- [{ product_code, name, price_usd, sort, max_qty }]
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_supplier public.suppliers;
  v_product_id bigint;
  v_slug text;
  v_item jsonb;
  v_variant_id bigint;
  v_fields jsonb;
  v_upserted integer := 0;
  v_deactivated integer := 0;
begin
  select * into v_supplier from public.suppliers where code = p_supplier_code;
  if not found then
    raise exception 'unknown_supplier' using detail = p_supplier_code;
  end if;

  v_slug := p_supplier_code || '-' || p_game_code;
  v_fields := public.supplier_field_definitions(p_required_fields);

  insert into public.products (
    slug, name_km, name_en, summary_km, summary_en, image_url, kind,
    requires_fields, supplier_id, supplier_game_code, is_active, sort_order
  ) values (
    v_slug, p_name, p_name, p_summary, p_summary, p_image_url, 'auto_topup',
    v_fields, v_supplier.id, p_game_code, true, 1000
  )
  on conflict (slug) do update
    set name_km       = excluded.name_km,
        name_en       = excluded.name_en,
        summary_km    = excluded.summary_km,
        summary_en    = excluded.summary_en,
        image_url     = coalesce(excluded.image_url, public.products.image_url),
        requires_fields = excluded.requires_fields,
        supplier_id   = excluded.supplier_id,
        supplier_game_code = excluded.supplier_game_code,
        -- Deliberately NOT is_active = true. A product is activated when it is
        -- first synced, but from then on the switch belongs to staff: hiding a
        -- broken game must survive the next sync. A game this sync hides
        -- because the supplier dropped every package stays hidden too, so
        -- selling something undeliverable is never the automatic outcome.
        -- Staff re-enable it with admin_product_set_active once the supplier
        -- lists it again.
        updated_at    = now()
  returning id into v_product_id;

  for v_item in select * from jsonb_array_elements(coalesce(p_products, '[]'::jsonb))
  loop
    if coalesce(btrim(v_item ->> 'product_code'), '') = '' then
      raise exception 'product_missing_code'
        using detail = left(v_item::text, 200);
    end if;

    insert into public.product_variants (
      product_id, sku, label_km, label_en, price_usd, cost_usd,
      stock_mode, min_qty, max_qty, is_active, sort_order
    ) values (
      v_product_id,
      (v_item ->> 'product_code'),
      (v_item ->> 'name'),
      (v_item ->> 'name'),
      -- The supplier price is cost. Retail is set by staff afterwards; until
      -- then it is cost, so an unpriced SKU can never be sold at a loss.
      round((v_item ->> 'price_usd')::numeric, 2),
      round((v_item ->> 'price_usd')::numeric, 2),
      'unlimited',
      -- 50 is the default for a supplier whose API takes a quantity. A
      -- supplier that cannot is capped at one unit per line by the sync.
      coalesce((v_item ->> 'min_qty')::int, 1),
      coalesce((v_item ->> 'max_qty')::int, 50),
      true,
      coalesce((v_item ->> 'sort')::int, 0)
    )
    on conflict (sku) do update
      set label_km   = excluded.label_km,
          label_en   = excluded.label_en,
          -- Read the OLD cost before it is overwritten below: an unpriced SKU
          -- (price = old cost) follows the supplier; a staff price does not.
          price_usd  = case
                         when public.product_variants.price_usd = public.product_variants.cost_usd
                           then excluded.cost_usd
                         else public.product_variants.price_usd
                       end,
          cost_usd   = excluded.cost_usd,
          -- Quantity bounds follow the supplier's capability, so a re-sync
          -- repairs rows written before the cap existed.
          min_qty    = excluded.min_qty,
          max_qty    = excluded.max_qty,
          sort_order = excluded.sort_order,
          is_active  = true,
          product_id = excluded.product_id
    returning id into v_variant_id;

    insert into public.supplier_skus (
      supplier_id, variant_id, supplier_sku, cost_usd, is_active, last_synced_at, last_cost_usd
    ) values (
      v_supplier.id, v_variant_id, (v_item ->> 'product_code'),
      round((v_item ->> 'price_usd')::numeric, 2), true, now(),
      round((v_item ->> 'price_usd')::numeric, 2)
    )
    on conflict (supplier_id, variant_id, supplier_sku) do update
      set cost_usd       = excluded.cost_usd,
          last_cost_usd  = excluded.last_cost_usd,
          last_synced_at = now(),
          is_active      = true;

    v_upserted := v_upserted + 1;
  end loop;

  -- ------------------------------------------------------------------------
  -- Reconcile: only when the pull actually returned products.
  -- ------------------------------------------------------------------------
  if jsonb_array_length(coalesce(p_products, '[]'::jsonb)) > 0 then
    -- Variants this supplier no longer lists for the game. Scoped to variants
    -- this supplier actually fulfils, so a staff-made or locally stocked line
    -- on the same product is never switched off by a sync.
    update public.product_variants v
       set is_active = false
     where v.product_id = v_product_id
       and v.is_active
       and exists (
         select 1 from public.supplier_skus s
          where s.variant_id = v.id and s.supplier_id = v_supplier.id
       )
       and v.sku not in (
         select (i ->> 'product_code') from jsonb_array_elements(p_products) i
       );

    get diagnostics v_deactivated = row_count;

    -- Their SKU links follow. An order already paid for a line whose SKU just
    -- disappeared becomes a staff problem rather than a silent retry loop: the
    -- supplier would reject the product_code anyway, so there is nothing left
    -- to attempt automatically.
    update public.supplier_skus s
       set is_active = false
     where s.supplier_id = v_supplier.id
       and s.is_active
       and not exists (
         select 1 from public.product_variants v
          where v.id = s.variant_id and v.is_active
       );

    -- A game with nothing on sale is hidden, not shown as an empty shelf.
    --
    -- Swept across this supplier's whole catalogue, not just the game being
    -- synced: a SKU can also leave a product by moving to another game, since
    -- the variant upsert reassigns product_id when the supplier reuses a
    -- product_code. That product is not named anywhere in this call.
    update public.products p
       set is_active = false,
           updated_at    = now()
     where p.supplier_id = v_supplier.id
       and p.is_active
       and not exists (
         select 1 from public.product_variants v
          where v.product_id = p.id and v.is_active
       );
  end if;

  return jsonb_build_object(
    'product_id', v_product_id,
    'slug', v_slug,
    'variants_synced', v_upserted,
    'variants_deactivated', v_deactivated
  );
end;
$$;

revoke execute on function public.supplier_upsert_catalogue(text, text, text, text, text, jsonb, jsonb)
  from public, anon, authenticated;


-- ============================================================================
-- 20261016130000_supplier_manual_fallback.sql
-- ============================================================================

do $$ begin raise notice '>>> 20261016130000_supplier_manual_fallback.sql'; end $$;

-- ============================================================================
-- An auto top-up that no supplier can deliver is a staff job, not a pending one.
--
-- `private.deliver_order` marks every `auto_topup` line `pending` and leaves it
-- for the supplier worker. That is right when a supplier is linked. It is wrong
-- when the variant has no active supplier SKU at all:
--
--   * `supplier_pending_items` returns it with a null `supplier_sku`, so the
--     worker can only defer it and never deliver it;
--   * the line never records an attempt, and `admin_supplier_queue` lists only
--     lines that are `manual_waiting` or have `supplier_attempts > 0`;
--
-- so the order sits in `delivering` for ever, invisible to the only person who
-- could finish it. The demo catalogue hits this: `mobile-legends-diamonds` is
-- `auto_topup` with no supplier link, and every purchase of it parks there.
--
-- Two pieces:
--
--   private.deliver_order                  auto_topup: linked -> pending
--                                                      unlinked -> manual_waiting
--   public.supplier_backfill_unlinked_items()   the same repair for lines that
--                                          are already stuck, run once here
--
-- An unlinked line is not an error state. It means "a person delivers this",
-- which is exactly what `manual_waiting` says everywhere else in the schema.
-- ============================================================================

create or replace function private.deliver_order(p_order_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_item      record;
  v_picked    integer;
  v_pending   integer;
  v_waiting   integer;
  v_all_done  boolean;
begin
  update public.orders set status = 'delivering' where id = p_order_id and status = 'paid';

  for v_item in
    select oi.id, oi.variant_id, oi.qty, p.kind, oi.product_name,
           -- Whether a worker could ever finish this line: it needs an active
           -- supplier SKU to order. The supplier row's own `is_active` is
           -- deliberately not part of this: it is a switch staff flip, sometimes
           -- off for a day, and `supplier_pending_items` still hands those lines
           -- to the worker on purpose, which defers them and escalates to staff
           -- after the attempt limit. What can never be delivered, and so must
           -- not pretend to wait for a worker, is a line with no SKU behind it.
           exists (
             select 1
               from public.supplier_skus ss
              where ss.variant_id = v.id
                and ss.is_active
           ) as has_supplier
      from public.order_items oi
      join public.product_variants v on v.id = oi.variant_id
      join public.products p on p.id = v.product_id
     where oi.order_id = p_order_id
       and oi.delivery_status = 'pending'
     order by oi.id
  loop
    if v_item.kind = 'instant_stock' then
      -- The one statement that prevents double-selling.
      update private.stock_items s
         set status = 'sold', order_id = p_order_id, sold_at = now()
       where s.id in (
         select id
           from private.stock_items
          where variant_id = v_item.variant_id
            and status = 'available'
          order by created_at
          limit v_item.qty
          for update skip locked
       );

      get diagnostics v_picked = row_count;

      if v_picked = v_item.qty then
        update public.order_items
           set delivery_status = 'delivered', delivered_at = now()
         where id = v_item.id;

        update public.products
           set sold_count = sold_count + v_item.qty
         where id = (select product_id from public.product_variants where id = v_item.variant_id);
      else
        -- Roll back a short pick so nothing is stranded mid-order.
        if v_picked > 0 then
          update private.stock_items
             set status = 'available', order_id = null, sold_at = null
           where order_id = p_order_id
             and variant_id = v_item.variant_id
             and status = 'sold'
             and id in (select id from private.stock_items
                         where order_id = p_order_id and variant_id = v_item.variant_id
                         order by id desc limit v_picked);
        end if;

        update public.order_items
           set delivery_status = 'manual_waiting'
         where id = v_item.id;
      end if;

    elsif v_item.kind = 'manual_setup' then
      update public.order_items
         set delivery_status = 'manual_waiting'
       where id = v_item.id;

    elsif v_item.has_supplier then
      -- auto_topup with a supplier: a worker calls their API and flips this row.
      update public.order_items
         set delivery_status = 'pending'
       where id = v_item.id;

    else
      -- auto_topup with nothing to call: staff deliver it by hand.
      update public.order_items
         set delivery_status = 'manual_waiting'
       where id = v_item.id;
    end if;
  end loop;

  select
    count(*) filter (where delivery_status = 'pending'),
    count(*) filter (where delivery_status = 'manual_waiting')
    into v_pending, v_waiting
    from public.order_items where order_id = p_order_id;

  v_all_done := (v_pending = 0 and v_waiting = 0);

  update public.orders
     set status = case when v_all_done then 'delivered'::public.order_status else 'delivering'::public.order_status end,
         delivered_at = case when v_all_done then now() else delivered_at end
   where id = p_order_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- The repair for lines delivered before the rule above existed.
--
-- Orders already sitting in `delivering` on an unlinked auto top-up line are
-- the exact case this migration is about, and nothing would move them: the
-- worker cannot claim them and staff cannot see them. This flips them to
-- `manual_waiting`, where `admin_supplier_queue` picks them up.
--
-- Only orders that are actually waiting on delivery are touched. A `pending`
-- line on an expired order is not stuck, it is simply an order that was never
-- paid, and dragging those into the staff queue would bury the real work.
--
-- Kept as a function rather than a bare `update` so it is re-runnable: a later
-- migration, or a supplier being unlinked by hand, can leave the same debris.
-- ---------------------------------------------------------------------------
create or replace function public.supplier_backfill_unlinked_items()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare v_moved integer;
begin
  update public.order_items oi
     set delivery_status = 'manual_waiting'
    from public.product_variants v
    join public.products p on p.id = v.product_id
   where v.id = oi.variant_id
     and oi.delivery_status = 'pending'
     and p.kind = 'auto_topup'
     and exists (
       select 1 from public.orders o
        where o.id = oi.order_id
          and o.status in ('paid', 'delivering')
     )
     and not exists (
       select 1
         from public.supplier_skus ss
        where ss.variant_id = v.id
          and ss.is_active
     );

  get diagnostics v_moved = row_count;

  -- The order's own status does not change: it is still 'delivering', because
  -- the goods are still owed. Only the person responsible changes.
  return v_moved;
end;
$$;

-- Operator/support function, like the other `admin_*` repairs: definer, so it
-- can read the private tables, and reachable from the SQL editor rather than
-- from a client.
revoke execute on function public.supplier_backfill_unlinked_items() from public, anon, authenticated;

do $$
declare v_moved integer;
begin
  select public.supplier_backfill_unlinked_items() into v_moved;
  raise notice 'supplier_manual_fallback: % stuck auto top-up line(s) handed to staff', v_moved;
end $$;


-- ============================================================================
-- 20261020160000_banner_art.sql
-- ============================================================================

do $$ begin raise notice '>>> 20261020160000_banner_art.sql'; end $$;

-- Banner art for the home spotlight.
--
-- A supplier game arrives with one square image (`products.image_url`), which
-- is right for a card but wrong for the wide panel at the top of home: cropped
-- to fit it loses the logo, contained it leaves dead space.
--
-- `banner_url` holds a wide, mirrored image instead. It is resolved by the
-- `game-banner` Edge Function from IGDB key art, or set by staff with an
-- explicit URL, and copied into the `product-images` bucket so the browser can
-- load it (IGDB lets us hotlink, but the mirror keeps us independent of them).
--
-- Null is normal: the spotlight falls back to the square art on a blurred
-- backdrop. Nothing reads this yet at order time, so it is display-only.
alter table public.products
  add column if not exists banner_url text;

comment on column public.products.banner_url is
  'Wide banner art for the home spotlight. Mirrored into product-images; null falls back to image_url.';


-- ============================================================================
-- 20261025090000_dodo_provider.sql
-- ============================================================================

do $$ begin raise notice '>>> 20261025090000_dodo_provider.sql'; end $$;

-- Dodo Payments as a second payment provider.
--
-- PayWay settles ABA KHQR in riel-friendly, local rails. Dodo is the card
-- rail: an international Merchant of Record that handles tax and disputes for
-- buyers who cannot scan a KHQR.
--
-- The value is added here on its own. Postgres refuses to use a new enum value
-- in the same transaction that adds it, and each migration file is one
-- transaction; the file that writes 'dodo' rows comes next.
alter type public.payment_provider add value if not exists 'dodo';


-- ============================================================================
-- 20261025090100_dodo_checkout.sql
-- ============================================================================

do $$ begin raise notice '>>> 20261025090100_dodo_checkout.sql'; end $$;

-- Dodo checkout bookkeeping.
--
-- A Dodo payment has two identifiers, and they appear at different times:
--
--   * `cks_...` the checkout session, returned when the session is created.
--     It is what the app polls, because the payment id does not exist until
--     the buyer has actually paid.
--   * `pay_...` the payment, returned by the webhook and by the session once
--     it succeeds. This is the id that settles the order, so it goes in
--     `provider_ref`, which already carries the unique index that makes
--     settlement idempotent.
--
-- `provider_session_id` therefore gets its own column. Reusing `provider_ref`
-- for both would either collide on the unique index or leave a pending row
-- whose id silently changes under it.
alter table public.payments
  add column if not exists provider_session_id text;

comment on column public.payments.provider_session_id is
  'Dodo checkout session id (cks_...). provider_ref holds the payment id (pay_...) once it exists.';

create unique index if not exists payments_provider_session_idx
  on public.payments (provider, provider_session_id)
  where provider_session_id is not null;

-- The card option is opt-in. A fresh project has no Dodo keys, and a payment
-- tile that always fails is worse than no tile at all. Staff flip this on once
-- the product and keys exist.
alter table public.settings
  add column if not exists dodo_enabled boolean not null default false;

comment on column public.settings.dodo_enabled is
  'Show the card (Dodo) payment option at checkout. Requires DODO_* Edge secrets and a Pay What You Want product.';

-- The app reads the view, not the table.
create or replace view public.public_settings as
select
  id, site_name, support_telegram, support_email, usd_to_khr, order_ttl_minutes,
  khqr_account_id, khqr_merchant_name, khqr_merchant_city, is_maintenance,
  topup_min_usd, topup_max_usd, telegram_bot_username, manual_grace_minutes,
  dodo_enabled
from public.settings;

grant select on public.public_settings to anon, authenticated;
